def build_komika_flatbuffer(base_764_bytes: bytes, text: str, rgb_tuple: tuple) -> bytes:
    txt_bytes = text.encode("utf-8")
    slen = len(txt_bytes)
    str_pad_len = ((slen + 2) // 4) * 4 + 2
    delta = str_pad_len - 14
    header = bytearray(base_764_bytes[:596])
    struct.pack_into("<I", header, 0, 752 + delta)
    struct.pack_into("<i", header, 256, -490 - delta)
    struct.pack_into("<i", header, 348, -360 - delta)
    struct.pack_into("<i", header, 364, -362 - delta)
    struct.pack_into("<i", header, 492, -224 - delta)
    struct.pack_into("<i", header, 520, -226 - delta)
    struct.pack_into("<i", header, 528, -180 - delta)
    struct.pack_into("<i", header, 532, -176 - delta)
    struct.pack_into("<i", header, 536, -210 - delta)
    struct.pack_into("<I", header, 592, 76 + delta)
    tail = bytearray(base_764_bytes[-150:])
    tail[-3:] = bytes(rgb_tuple)
    return bytes(header) + struct.pack("<I", slen) + txt_bytes.ljust(str_pad_len, b"\x00") + bytes(tail)


def set_a1_intro_ducking(a1_el, db_level, kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid):
    donor_comp_oid = "7029" if db_level == 0 else ("7045" if db_level == -10 else "7035")
    new_comp_id, _, _ = clone_subgraph_into(
        "id", donor_comp_oid, kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid
    )
    comps_ref = a1_el.find(".//Components")
    if comps_ref is not None:
        comps_ref.attrib["ObjectRef"] = str(new_comp_id)
    props = a1_el.find("./ClipTrackItem/TrackItem/Node/Properties")
    if props is not None:
        v1_el = props.find("ESP.VolumeSection.1")
        if v1_el is None:
            v1_el = ET.SubElement(props, "ESP.VolumeSection.1")
        v1_el.text = "0" if db_level == 0 else "1"
        v2_el = props.find("ESP.VolumeSection.2")
        if v2_el is None:
            v2_el = ET.SubElement(props, "ESP.VolumeSection.2")
        v2_el.text = "0" if db_level == 0 else ("-9.9999961853" if db_level == -10 else "-14.9999923706")


def mute_a1_trackitem(a1_el, kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid):
    new_comp_id, id_map, _ = clone_subgraph_into(
        "id", "7035", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid
    )
    for new_oid in id_map.values():
        p_el = dst_by_id.get(new_oid)
        if p_el is not None and p_el.tag == "AudioComponentParam" and p_el.findtext("Name") == "Level":
            skf_el = p_el.find("StartKeyframe")
            if skf_el is not None:
                skf_el.text = "-91445760000000000,0.,0,0,0,0,0,0"
            cv_el = p_el.find("CurrentValue")
            if cv_el is not None:
                cv_el.text = "0."
            kfs_el = p_el.find("Keyframes")
            if kfs_el is not None:
                kfs_el.text = None
    comps_ref = a1_el.find(".//Components")
    if comps_ref is not None:
        comps_ref.attrib["ObjectRef"] = str(new_comp_id)
    props = a1_el.find("./ClipTrackItem/TrackItem/Node/Properties")
    if props is not None:
        v1_el = props.find("ESP.VolumeSection.1")
        if v1_el is None:
            v1_el = ET.SubElement(props, "ESP.VolumeSection.1")
        v1_el.text = "1"
        v2_el = props.find("ESP.VolumeSection.2")
        if v2_el is None:
            v2_el = ET.SubElement(props, "ESP.VolumeSection.2")
        v2_el.text = "-60"


def strip_transitions_from_ti(ti_el):
    cti = ti_el.find("ClipTrackItem")
    if cti is not None:
        for t in list(cti):
            if t.tag in ("HeadTransition", "TailTransition"):
                cti.remove(t)


def attach_transition_refs(out_ti_el, in_ti_el, trans_oid):
    if out_ti_el is not None:
        cti = out_ti_el.find("ClipTrackItem")
        if cti is not None:
            for t in list(cti):
                if t.tag == "TailTransition":
                    cti.remove(t)
            sc = cti.find("SubClip")
            ht = cti.find("HeadTransition")
            ins_idx = list(cti).index(ht) + 1 if ht is not None else (list(cti).index(sc) + 1 if sc is not None else len(cti))
            tt = ET.Element("TailTransition", {"ObjectRef": str(trans_oid)})
            cti.insert(ins_idx, tt)
    if in_ti_el is not None:
        cti = in_ti_el.find("ClipTrackItem")
        if cti is not None:
            for t in list(cti):
                if t.tag == "HeadTransition":
                    cti.remove(t)
            sc = cti.find("SubClip")
            ins_idx = list(cti).index(sc) + 1 if sc is not None else len(cti)
            ht = ET.Element("HeadTransition", {"ObjectRef": str(trans_oid)})
            cti.insert(ins_idx, ht)


def load_xml(path):
    with gzip.open(path, "rb") as f:
        root = ET.fromstring(f.read())
    by_id = {el.attrib["ObjectID"]: el for el in root if "ObjectID" in el.attrib}
    by_uid = {el.attrib["ObjectUID"]: el for el in root if "ObjectUID" in el.attrib}
    return root, by_id, by_uid


def iter_no_pvs(el):
    if el.tag == "ProjectViewState.List":
        return
    yield el
    for c in el:
        yield from iter_no_pvs(c)


def iter_for_clone(el):
    if el.tag in ("ProjectViewState.List", "HeadTransition", "TailTransition", "Links"):
        return
    yield el
    for c in el:
        yield from iter_for_clone(c)


def collect_subgraph(start_kind, start_key, by_id, by_uid, stop_ids=None, stop_uids=None):
    stop_ids = stop_ids or set()
    stop_uids = stop_uids or set()
    visited_id, visited_uid = [], []
    seen_id, seen_uid = set(), set()
    queue = [(start_kind, start_key)]
    while queue:
        kind, key = queue.pop(0)
        if kind == "id":
            if key in seen_id or key in stop_ids or key not in by_id:
                continue
            seen_id.add(key)
            visited_id.append(key)
            el = by_id[key]
        else:
            if key in seen_uid or key in stop_uids or key not in by_uid:
                continue
            seen_uid.add(key)
            visited_uid.append(key)
            el = by_uid[key]
        for sub in iter_for_clone(el):
            if "ObjectRef" in sub.attrib:
                queue.append(("id", sub.attrib["ObjectRef"]))
            if "ObjectURef" in sub.attrib:
                queue.append(("uid", sub.attrib["ObjectURef"]))
    return visited_id, visited_uid


def clone_subgraph_into(start_kind, start_key, src_id, src_uid, dst_root, next_oid_fn, dst_by_id=None, dst_by_uid=None, stop_ids=None, stop_uids=None):
    vis_ids, vis_uids = collect_subgraph(start_kind, start_key, src_id, src_uid, stop_ids, stop_uids)
    id_map = {old_id: str(next_oid_fn()) for old_id in vis_ids}
    uid_map = {old_uid: str(uuid.uuid4()) for old_uid in vis_uids}

    cloned_els = []
    for old_id in vis_ids:
        el = copy.deepcopy(src_id[old_id])
        el.attrib["ObjectID"] = id_map[old_id]
        cloned_els.append(el)
        if dst_by_id is not None:
            dst_by_id[id_map[old_id]] = el
    for old_uid in vis_uids:
        el = copy.deepcopy(src_uid[old_uid])
        el.attrib["ObjectUID"] = uid_map[old_uid]
        cloned_els.append(el)
        if dst_by_uid is not None:
            dst_by_uid[uid_map[old_uid]] = el

    for el in cloned_els:
        if el.tag in ("VideoClipTrackItem", "AudioClipTrackItem"):
            cti = el.find("ClipTrackItem")
            if cti is not None:
                for t in list(cti):
                    if t.tag in ("HeadTransition", "TailTransition"):
                        cti.remove(t)
                    elif t.tag == "Links":
                        t.clear()
                        t.attrib["Version"] = "1"
        for sub in iter_no_pvs(el):
            if "ObjectRef" in sub.attrib and sub.attrib["ObjectRef"] in id_map:
                sub.attrib["ObjectRef"] = id_map[sub.attrib["ObjectRef"]]
            if "ObjectURef" in sub.attrib and sub.attrib["ObjectURef"] in uid_map:
                sub.attrib["ObjectURef"] = uid_map[sub.attrib["ObjectURef"]]
            if sub.tag == "ClipID" and (sub.text or "").strip():
                sub.text = str(uuid.uuid4())
            if el.tag in ("VideoClipTrackItem", "AudioClipTrackItem") and sub.tag == "ID" and "-" in (sub.text or ""):
                sub.text = str(uuid.uuid4())
        dst_root.append(el)

    root_new_key = id_map[start_key] if start_kind == "id" else uid_map[start_key]
    return root_new_key, id_map, uid_map



def set_trackitem_timing(ti_el, dst_by_id, start_ticks, end_ticks, preserve_inpoint=True, explicit_in_ticks=None):
    ti_inner = ti_el.find("./ClipTrackItem/TrackItem")
    if ti_inner is None:
        ti_inner = ti_el.find("TrackItem")
    if ti_inner is None:
        return
    st_el = ti_inner.find("Start")
    en_el = ti_inner.find("End")
    if start_ticks > 0:
        if st_el is None:
            st_el = ET.Element("Start")
            en_idx = list(ti_inner).index(en_el) if en_el is not None else 0
            ti_inner.insert(en_idx, st_el)
        st_el.text = str(int(start_ticks))
    else:
        if st_el is not None:
            ti_inner.remove(st_el)
    if en_el is None:
        en_el = ET.SubElement(ti_inner, "End")
    en_el.text = str(int(end_ticks))

    sc_ref = ti_el.find(".//SubClip")
    if sc_ref is not None and sc_ref.attrib.get("ObjectRef") in dst_by_id:
        sc_el = dst_by_id[sc_ref.attrib["ObjectRef"]]
        c_ref = sc_el.find(".//Clip")
        if c_ref is not None and c_ref.attrib.get("ObjectRef") in dst_by_id:
            c_el = dst_by_id[c_ref.attrib["ObjectRef"]]
            ip_el = c_el.find(".//InPoint")
            op_el = c_el.find(".//OutPoint")
            if explicit_in_ticks is not None:
                in_val = int(explicit_in_ticks)
            else:
                in_val = int(ip_el.text) if (preserve_inpoint and ip_el is not None and ip_el.text) else 0
            if ip_el is not None:
                ip_el.text = str(in_val)
            if op_el is not None:
                op_el.text = str(in_val + int(end_ticks - start_ticks))


def set_transition_timing(tr_el, start_ticks, end_ticks, alignment_ticks, has_outgoing=True, has_incoming=True):
    tti = tr_el.find("TransitionTrackItem")
    if tti is None:
        return
    ti_inner = tti.find("TrackItem")
    if ti_inner is None:
        ti_inner = ET.Element("TrackItem", {"Version": "4"})
        tti.insert(0, ti_inner)
    st_el = ti_inner.find("Start")
    en_el = ti_inner.find("End")
    if start_ticks > 0:
        if st_el is None:
            st_el = ET.Element("Start")
            en_idx = list(ti_inner).index(en_el) if en_el is not None else 0
            ti_inner.insert(en_idx, st_el)
        st_el.text = str(int(start_ticks))
    else:
        if st_el is not None:
            ti_inner.remove(st_el)
    if en_el is None:
        en_el = ET.SubElement(ti_inner, "End")
    en_el.text = str(int(end_ticks))

    al_el = tti.find("Alignment")
    if al_el is None:
        al_el = ET.SubElement(tti, "Alignment")
    al_el.text = str(int(alignment_ticks))

    ho_el = tti.find("HasOutgoingClip")
    if ho_el is None:
        ho_el = ET.SubElement(tti, "HasOutgoingClip")
    ho_el.text = "true" if has_outgoing else "false"

    hi_el = tti.find("HasIncomingClip")
    if hi_el is None:
        hi_el = ET.SubElement(tti, "HasIncomingClip")
    hi_el.text = "true" if has_incoming else "false"


def set_subclip_name(ti_el, dst_by_id, new_name):
    sc_ref = ti_el.find(".//SubClip")
    if sc_ref is not None and sc_ref.attrib.get("ObjectRef") in dst_by_id:
        sc_el = dst_by_id[sc_ref.attrib["ObjectRef"]]
        nm_el = sc_el.find("Name")
        if nm_el is not None:
            nm_el.text = new_name


def is_viralhog_clip(clip_name, vh_names):
    if clip_name in vh_names:
        return True
    for k in vh_names:
        base = k.replace(".mp4", "")
        if len(base) >= 2 and (clip_name == k or clip_name.startswith(base + "_")):
            return True
    return False


def set_clip_scale(
    ti_el,
    dst_by_id,
    dst_by_uid,
    dst_root=None,
    next_oid=None,
    donor_motion_comp_id=None,
    scale_val=120.0,
    pos_xy=(0.5, 0.5),
):
    def _deref(ref):
        if ref is None:
            return None
        if "ObjectRef" in ref.attrib:
            return dst_by_id.get(ref.attrib["ObjectRef"])
        if "ObjectURef" in ref.attrib:
            return dst_by_uid.get(ref.attrib["ObjectURef"])
        return None

    comps_ref = ti_el.find(".//Components")
    if comps_ref is None:
        return
    chain_el = _deref(comps_ref)
    if chain_el is None:
        return

    # Check if a Motion component already exists
    motion_comp = None
    for cref in chain_el.iter("Component"):
        comp = _deref(cref)
        if comp is not None and "AE.ADBE Motion" in (comp.findtext(".//MatchName") or ""):
            motion_comp = comp
            break

    if motion_comp is None and donor_motion_comp_id is not None and dst_root is not None and next_oid is not None:
        new_comp_id, _, _ = clone_subgraph_into(
            "id", donor_motion_comp_id, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid
        )
        motion_comp = dst_by_id[new_comp_id]
        dm = chain_el.find("DefaultMotion")
        if dm is not None:
            chain_el.remove(dm)
        cc_el = chain_el.find("ComponentChain")
        if cc_el is not None:
            comps_el = cc_el.find("Components")
            if comps_el is None:
                comps_el = ET.SubElement(cc_el, "Components", {"Version": "1"})
            ET.SubElement(comps_el, "Component", {"Index": str(len(comps_el)), "ObjectRef": str(new_comp_id)})

    if motion_comp is not None:
        px, py = float(pos_xy[0]), float(pos_xy[1])
        for pref in motion_comp.iter("Param"):
            prm = _deref(pref)
            if prm is None:
                continue
            pnm = prm.findtext("Name")
            if pnm == "Scale":
                skf = prm.find("StartKeyframe")
                if skf is not None:
                    skf.text = f"-91445760000000000,{float(scale_val):.2f},0,0,0,0,0,0"
                val = prm.find("Value")
                if val is not None:
                    val.text = f"{float(scale_val):.2f}"
                cur = prm.find("CurrentValue")
                if cur is None:
                    cur = ET.SubElement(prm, "CurrentValue")
                cur.text = f"{float(scale_val):.2f}"
                kfs_el = prm.find("Keyframes")
                if kfs_el is not None:
                    kfs_el.text = None
            elif pnm == "Position":
                skf = prm.find("StartKeyframe")
                if skf is None:
                    skf = ET.SubElement(prm, "StartKeyframe")
                skf.text = f"-91445760000000000,{px:.6f}:{py:.6f},0,0,0,0,0,0,5,4,0,0,0,0"
                kfs_el = prm.find("Keyframes")
                if kfs_el is not None:
                    kfs_el.text = None


def set_emoji_motion_keyframes(ti_el, dst_by_id, dst_by_uid, dst_root=None, next_oid=None, donor_motion_comp_id=None, dur_ticks=0, scale_val=100.0, points=None):
    def _deref(ref):
        if ref is None:
            return None
        if "ObjectRef" in ref.attrib:
            return dst_by_id.get(ref.attrib["ObjectRef"])
        if "ObjectURef" in ref.attrib:
            return dst_by_uid.get(ref.attrib["ObjectURef"])
        return None

    if points is None:
        points = [(0.35, 0.62), (0.36, 0.64), (0.38, 0.67), (0.39, 0.70)]

    comps_ref = ti_el.find(".//Components")
    if comps_ref is None:
        return
    chain_el = _deref(comps_ref)
    if chain_el is None:
        return

    # Check if a Motion component already exists
    motion_comp = None
    for cref in chain_el.iter("Component"):
        comp = _deref(cref)
        if comp is not None and "AE.ADBE Motion" in (comp.findtext(".//MatchName") or ""):
            motion_comp = comp
            break

    if motion_comp is None and donor_motion_comp_id is not None and dst_root is not None and next_oid is not None:
        new_comp_id, _, _ = clone_subgraph_into(
            "id", donor_motion_comp_id, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid
        )
        motion_comp = dst_by_id[new_comp_id]
        dm = chain_el.find("DefaultMotion")
        if dm is not None:
            chain_el.remove(dm)
        cc_el = chain_el.find("ComponentChain")
        if cc_el is not None:
            comps_el = cc_el.find("Components")
            if comps_el is None:
                comps_el = ET.SubElement(cc_el, "Components", {"Version": "1"})
            ET.SubElement(comps_el, "Component", {"Index": str(len(comps_el)), "ObjectRef": str(new_comp_id)})

    if motion_comp is not None:
        for pref in motion_comp.iter("Param"):
            prm = _deref(pref)
            if prm is None:
                continue
            nm = prm.findtext("Name")
            if nm == "Position":
                x0, y0 = points[0]
                skf_el = prm.find("StartKeyframe")
                if skf_el is None:
                    skf_el = ET.SubElement(prm, "StartKeyframe")
                skf_el.text = f"-91445760000000000,{x0:.6f}:{y0:.6f},0,0,0,0,0,0,5,4,0,0,0,0"
                kfs_el = prm.find("Keyframes")
                if kfs_el is None:
                    kfs_el = ET.SubElement(prm, "Keyframes")
                n_pts = len(points)
                kf_parts = []
                for i, (px, py) in enumerate(points):
                    t_tick = int(round(i * dur_ticks / max(1, n_pts - 1)))
                    kf_parts.append(
                        f"{t_tick},{px:.6f}:{py:.6f},0,0,0,0.16666666666666666,0,0.16666666666666666,5,4,0,0,0,0;"
                    )
                kfs_el.text = "".join(kf_parts)
            elif nm == "Scale":
                skf_el = prm.find("StartKeyframe")
                if skf_el is not None:
                    skf_el.text = f"-91445760000000000,{float(scale_val):.2f},0,0,0,0,0,0"
                val = prm.find("Value")
                if val is not None:
                    val.text = f"{float(scale_val):.2f}"
                cur = prm.find("CurrentValue")
                if cur is None:
                    cur = ET.SubElement(prm, "CurrentValue")
                cur.text = f"{float(scale_val):.2f}"
                kfs_el = prm.find("Keyframes")
                if kfs_el is not None:
                    kfs_el.text = None


def strip_lumetri_from_ti(ti_el, dst_by_id, strip_blur=False, strip_crop=False):
    comps_ref = ti_el.find(".//Components")
    if comps_ref is None:
        return
    chain_ref = comps_ref.attrib.get("ObjectRef")
    chain_el = dst_by_id.get(chain_ref)
    if chain_el is None:
        return
    comps_el = chain_el.find("./ComponentChain/Components")
    if comps_el is None:
        return
    drop_names = {"AE.ADBE Lumetri"}
    if strip_blur:
        drop_names.add("AE.Impact_Blur_FX")
    if strip_crop:
        drop_names.add("AE.ADBE AECrop")
        drop_names.add("AE.ADBE Crop")
    kept = []
    for c in comps_el.findall("Component"):
        cid = c.attrib["ObjectRef"]
        comp = dst_by_id.get(cid)
        if comp is not None and (comp.findtext(".//MatchName") or "") in drop_names:
            continue
        kept.append(cid)
    comps_el.clear()
    comps_el.attrib["Version"] = "1"
    for idx, cid in enumerate(kept):
        sub = ET.SubElement(comps_el, "Component")
        sub.attrib["Index"] = str(idx)
        sub.attrib["ObjectRef"] = cid


def build_rect_mask_spec(x1: float, y1: float, x2: float, y2: float, idx: int = 1) -> dict:
    raw_134 = (
        struct.pack("<IIIBII", 2, 1, 0x00007956, 0, 2, 4)
        + b"".join(
            struct.pack("<I6f", 0, float(vx), float(vy), float(vx), float(vy), float(vx), float(vy))
            for vx, vy in ((x1, y1), (x2, y1), (x2, y2), (x1, y2))
        )
        + b"\x01"
    )
    cx = 0.5 * (float(x1) + float(x2))
    cy = 0.5 * (float(y1) + float(y2))
    return {
        "instance_name": f"{idx:02d}",
        "path_b64": base64.b64encode(raw_134).decode("ascii"),
        "pos_skf": f"-91445760000000000,{cx:.16f}:{cy:.16f},0,0,0,0,0,0,5,4,0,0,0,0",
    }


def _apply_mask_spec_to_subcomp(
    sc_el, mspec, dst_by_id, bh_pool=None, feather_val: float = 28.0, expansion_val: float = 0.0
):
    if sc_el is None:
        return
    m_iname = sc_el.find("./Component/InstanceName")
    if m_iname is not None:
        m_iname.text = mspec["instance_name"]
    for pref in sc_el.findall(".//Param"):
        pel = dst_by_id.get(pref.attrib.get("ObjectRef"))
        if pel is None:
            continue
        pnm = pel.findtext("Name") or ""
        if pnm == "Path":
            skv_el = pel.find("StartKeyframeValue")
            if skv_el is not None:
                new_bh = str(uuid.uuid4())
                skv_el.attrib["BinaryHash"] = new_bh
                skv_el.text = mspec["path_b64"]
                if bh_pool is not None:
                    bh_pool[new_bh] = mspec["path_b64"]
        elif pnm in ("Position", "Anchor Point"):
            skf_el = pel.find("StartKeyframe")
            if skf_el is not None:
                skf_el.text = mspec["pos_skf"]
        elif pnm in ("Scale Height", "Scale Width"):
            skf_el = pel.find("StartKeyframe")
            if skf_el is not None:
                skf_el.text = "-91445760000000000,100.,0,0,0,0,0,0"
            cv_el = pel.find("CurrentValue")
            if cv_el is not None:
                cv_el.text = "100"
        elif pnm == "Feather":
            skf_el = pel.find("StartKeyframe")
            if skf_el is not None:
                skf_el.text = f"-91445760000000000,{int(round(feather_val))}.,0,0,0,0,0,0"
            cv_el = pel.find("CurrentValue")
            if cv_el is not None:
                cv_el.text = str(int(round(feather_val)))
        elif pnm == "Expansion":
            skf_el = pel.find("StartKeyframe")
            if skf_el is not None:
                skf_el.text = f"-91445760000000000,{int(round(expansion_val))}.,0,0,0,0,0,0"
            cv_el = pel.find("CurrentValue")
            if cv_el is not None:
                cv_el.text = str(int(round(expansion_val)))


def attach_blur_preset_from_kb116(
    ti_el, donor_blur_oid, kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid, bh_pool=None
):
    comps_ref = ti_el.find(".//Components")
    if comps_ref is None:
        return
    chain_el = dst_by_id.get(comps_ref.attrib.get("ObjectRef"))
    if chain_el is None:
        return
    cc_el = chain_el.find("ComponentChain")
    if cc_el is None:
        return
    comps_el = cc_el.find("Components")
    if comps_el is None:
        comps_el = ET.SubElement(cc_el, "Components", {"Version": "1"})

    is_custom_rects = isinstance(donor_blur_oid, (list, tuple))
    is_brac = donor_blur_oid == "brac"
    actual_donor_oid = "8058" if (is_brac or is_custom_rects) else donor_blur_oid
    new_blur_id, _, _ = clone_subgraph_into(
        "id", actual_donor_oid, kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid
    )

    if is_custom_rects:
        blur_comp = dst_by_id.get(new_blur_id)
        if blur_comp is not None:
            iname_el = blur_comp.find("./Component/InstanceName")
            if iname_el is not None:
                iname_el.text = "wm_shield"
            for b_pref in blur_comp.findall("./Component/Params/Param"):
                b_pel = dst_by_id.get(b_pref.attrib.get("ObjectRef"))
                if b_pel is not None and (b_pel.findtext("Name") or "") in ("Amount", "Thickness"):
                    if b_pel.find("StartKeyframe") is not None:
                        b_pel.find("StartKeyframe").text = "-91445760000000000,15.,0,0,0,0,0,0"
                    if b_pel.find("CurrentValue") is not None:
                        b_pel.find("CurrentValue").text = "15"
            ncn_el = blur_comp.find(".//BE.VideoFilterComponent.NextComponentNumber")
            if ncn_el is not None:
                ncn_el.text = str(len(donor_blur_oid))
            subcomps_el = blur_comp.find("SubComponents")
            if subcomps_el is None:
                subcomps_el = ET.SubElement(blur_comp, "SubComponents", {"Version": "1"})
            subcomps_el.clear()
            subcomps_el.attrib["Version"] = "1"
            for mask_idx, rect in enumerate(donor_blur_oid):
                x1, y1, x2, y2 = rect
                mspec = build_rect_mask_spec(x1, y1, x2, y2, idx=mask_idx + 1)
                new_sc_id, _, _ = clone_subgraph_into(
                    "id", "9688", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid
                )
                _apply_mask_spec_to_subcomp(
                    dst_by_id.get(new_sc_id), mspec, dst_by_id, bh_pool=bh_pool, feather_val=22.0, expansion_val=12.0
                )
                ET.SubElement(subcomps_el, "SubComponent", {"Index": str(mask_idx), "ObjectRef": str(new_sc_id)})
    elif is_brac:
        blur_comp = dst_by_id.get(new_blur_id)
        if blur_comp is not None:
            iname_el = blur_comp.find("./Component/InstanceName")
            if iname_el is not None:
                iname_el.text = "brac"
            sc_refs = blur_comp.findall("./SubComponents/SubComponent")
            for mask_idx, sc_ref in enumerate(sc_refs[:2]):
                mspec = BRAC_MASK_SPECS[mask_idx]
                sc_el = dst_by_id.get(sc_ref.attrib.get("ObjectRef"))
                _apply_mask_spec_to_subcomp(sc_el, mspec, dst_by_id, bh_pool=bh_pool, feather_val=35.0)

    ET.SubElement(comps_el, "Component", {"Index": str(len(comps_el)), "ObjectRef": str(new_blur_id)})


def apply_watermark_and_scale_policy(
    ti_el,
    clip_name,
    kb_id,
    is_vh,
    dst_by_id,
    dst_by_uid,
    kb111_id,
    kb111_uid,
    dst_root,
    next_oid,
    donor_motion_comp_id,
    donor_crop_comp_id=None,
    bh_pool=None,
):
    # Strip Lumetri, any legacy/stacked Impact_Blur_FX, and (for cloned kb122..124) inherited non-pillarbox AECrop
    should_strip_crop = (kb_id in ("kb122", "kb123", "kb124", "kb125", "kb126", "kb127", "kb128", "kb129", "kb130", "kb131", "kb132", "kb133", "kb134", "kb135", "kb136", "TEST_AUTO_WORKFAIL_9_11")) and (
        clip_name not in PILLARBOX_CROP_CLIPS.get(kb_id, set())
    )
    strip_lumetri_from_ti(ti_el, dst_by_id, strip_blur=True, strip_crop=should_strip_crop)

    custom_crop_pct = EPISODE_PILLARBOX_CROP_PCT.get(kb_id, {}).get(clip_name)

    # Check if clip has pillarbox crop (AE.ADBE AECrop)
    comps_ref = ti_el.find(".//Components")
    chain_el = dst_by_id.get(comps_ref.attrib.get("ObjectRef")) if comps_ref is not None else None
    cc_el = chain_el.find("ComponentChain") if chain_el is not None else None
    if cc_el is None and chain_el is not None:
        cc_el = ET.SubElement(chain_el, "ComponentChain", {"Version": "1"})
    comps_el = cc_el.find("Components") if cc_el is not None else None
    if comps_el is None and cc_el is not None:
        comps_el = ET.SubElement(cc_el, "Components", {"Version": "1"})
    has_pillar_crop = False
    if comps_el is not None:
        for c in comps_el.findall("Component"):
            comp = dst_by_id.get(c.attrib.get("ObjectRef"))
            if comp is None:
                continue
            mname = comp.findtext(".//MatchName") or ""
            if mname in ("AE.ADBE AECrop", "AE.ADBE Crop"):
                for pref in comp.findall(".//Param"):
                    prm = dst_by_id.get(pref.attrib.get("ObjectRef"))
                    if prm is None:
                        continue
                    pnm = prm.findtext("Name") or ""
                    if pnm in ("Left", "Right"):
                        skf = prm.findtext("StartKeyframe") or ""
                        if custom_crop_pct is not None:
                            has_pillar_crop = True
                            if prm.find("StartKeyframe") is not None:
                                prm.find("StartKeyframe").text = f"-91445760000000000,{float(custom_crop_pct):.5f},0,0,0,0,0,0"
                            if prm.find("CurrentValue") is not None:
                                prm.find("CurrentValue").text = f"{float(custom_crop_pct):.5f}"
                            if prm.find("Value") is not None:
                                prm.find("Value").text = f"{float(custom_crop_pct):.5f}"
                            if prm.find("Keyframes") is not None:
                                prm.find("Keyframes").text = None
                        elif "," in skf:
                            try:
                                val = float(skf.split(",")[1])
                                if val > 0.0:
                                    has_pillar_crop = True
                                    if val < 20.0 or val > 38.0:
                                        clamped = max(20.0, min(38.0, val))
                                        prm.find("StartKeyframe").text = f"-91445760000000000,{clamped:.5f},0,0,0,0,0,0"
                            except Exception:
                                pass
                    elif pnm in ("Top", "Bottom") and custom_crop_pct is not None:
                        if prm.find("StartKeyframe") is not None:
                            prm.find("StartKeyframe").text = "-91445760000000000,0.00000,0,0,0,0,0,0"
                        if prm.find("CurrentValue") is not None:
                            prm.find("CurrentValue").text = "0"

    if clip_name in PILLARBOX_CROP_CLIPS.get(kb_id, set()) and not has_pillar_crop and donor_crop_comp_id and comps_el is not None:
        target_crop = float(custom_crop_pct) if custom_crop_pct is not None else 28.0
        new_crop_id, crop_map, _ = clone_subgraph_into(
            "id", donor_crop_comp_id, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid
        )
        for new_oid in crop_map.values():
            prm = dst_by_id.get(new_oid)
            if prm is not None and prm.tag == "VideoComponentParam":
                pnm = prm.findtext("Name") or ""
                skf_el = prm.find("StartKeyframe")
                if skf_el is not None:
                    if pnm in ("Left", "Right"):
                        skf_el.text = f"-91445760000000000,{target_crop:.5f},0,0,0,0,0,0"
                        if prm.find("CurrentValue") is not None:
                            prm.find("CurrentValue").text = f"{target_crop:.5f}"
                    elif pnm in ("Top", "Bottom"):
                        skf_el.text = "-91445760000000000,0.00000,0,0,0,0,0,0"
                        if prm.find("CurrentValue") is not None:
                            prm.find("CurrentValue").text = "0"
        ET.SubElement(comps_el, "Component", {"Index": str(len(comps_el)), "ObjectRef": str(new_crop_id)})
        has_pillar_crop = True

    if is_vh:
        vh_ovr = EPISODE_VH_MOTION_OVERRIDE.get(kb_id, {}).get(clip_name)
        if vh_ovr is not None:
            vh_scale, vh_px, vh_py = vh_ovr
            set_clip_scale(ti_el, dst_by_id, dst_by_uid, dst_root, next_oid, donor_motion_comp_id, float(vh_scale), pos_xy=(vh_px, vh_py))
        else:
            set_clip_scale(ti_el, dst_by_id, dst_by_uid, dst_root, next_oid, donor_motion_comp_id, 120.0, pos_xy=(0.5, 0.5))
        return

    wm_spec = WATERMARK_PRESET_MAP.get(kb_id, {}).get(clip_name)
    if wm_spec is not None:
        if len(wm_spec) == 4:
            blur_oid, target_scale, w_px, w_py = wm_spec
        else:
            blur_oid, target_scale = wm_spec
            w_px, w_py = 0.5, 0.5
        set_clip_scale(ti_el, dst_by_id, dst_by_uid, dst_root, next_oid, donor_motion_comp_id, float(target_scale), pos_xy=(w_px, w_py))
        attach_blur_preset_from_kb116(
            ti_el, blur_oid, kb111_id, kb111_uid, dst_root, next_oid, dst_by_id, dst_by_uid, bh_pool=bh_pool
        )
    else:
        set_clip_scale(ti_el, dst_by_id, dst_by_uid, dst_root, next_oid, donor_motion_comp_id, 100.0, pos_xy=(0.5, 0.5))


_PROBE_CACHE = {}


def _probe_stream_meta(fp: str):
    k = os.path.normcase(fp)
    if k in _PROBE_CACHE:
        return _PROBE_CACHE[k]
    import subprocess
    meta = {"w": 1920, "h": 1080, "has_video": False, "has_audio": False, "dur_sec": 0.0}
    if fp and os.path.exists(fp):
        try:
            res = subprocess.run(
                [
                    "ffprobe",
                    "-v",
                    "error",
                    "-show_entries",
                    "stream=codec_type,width,height,duration:format=duration",
                    "-of",
                    "json",
                    fp,
                ],
                capture_output=True,
                text=True,
            )
            if res.returncode == 0 and res.stdout:
                info = json.loads(res.stdout)
                streams = info.get("streams", [])
                fmt_d = float(info.get("format", {}).get("duration") or 0.0)
                durs = [float(s["duration"]) for s in streams if s.get("duration")]
                meta["dur_sec"] = min(durs) if durs else fmt_d
                for s in streams:
                    if s.get("codec_type") == "video":
                        meta["has_video"] = True
                        meta["w"] = int(s.get("width") or 1920)
                        meta["h"] = int(s.get("height") or 1080)
                    elif s.get("codec_type") == "audio":
                        meta["has_audio"] = True
        except Exception:
            pass
    _PROBE_CACHE[k] = meta
    return meta


def sync_clip_media_and_stream_duration(
    ti_el, dst_by_id, dst_by_uid, clip_name, media_full_path, min_stream_ticks, update_media_path=False, proj_dir=None
):
    sc_ref = ti_el.find(".//SubClip")
    if sc_ref is None or sc_ref.attrib.get("ObjectRef") not in dst_by_id:
        return
    sc_el = dst_by_id[sc_ref.attrib["ObjectRef"]]

    c_ref = sc_el.find(".//Clip")
    if c_ref is None or c_ref.attrib.get("ObjectRef") not in dst_by_id:
        return
    c_el = dst_by_id[c_ref.attrib["ObjectRef"]]
    op_el = c_el.find(".//OutPoint")
    out_val = int(op_el.text) if (op_el is not None and op_el.text) else 0
    req_ticks = max(int(min_stream_ticks), out_val + TICKS_PER_FRAME)

    src_ref = c_el.find(".//Source")
    if src_ref is None or src_ref.attrib.get("ObjectRef") not in dst_by_id:
        return
    src_el = dst_by_id[src_ref.attrib["ObjectRef"]]
    m_ref = src_el.find(".//Media")
    if m_ref is None or m_ref.attrib.get("ObjectURef") not in dst_by_uid:
        return
    m_el = dst_by_uid[m_ref.attrib["ObjectURef"]]

    cur_fp = (m_el.findtext("FilePath") or "").strip()
    do_path_update = update_media_path or (bool(media_full_path) and cur_fp != media_full_path)
    effective_fp = media_full_path or cur_fp

    if do_path_update and clip_name:
        mc_ref = sc_el.find("MasterClip")
        if mc_ref is not None and mc_ref.attrib.get("ObjectURef") in dst_by_uid:
            mc_el = dst_by_uid[mc_ref.attrib["ObjectURef"]]
            nm_el = mc_el.find("Name")
            if nm_el is not None:
                nm_el.text = clip_name

    if do_path_update and media_full_path:
        for tag_nm in ("FilePath", "ActualMediaFilePath"):
            fp_el = m_el.find(tag_nm)
            if fp_el is not None:
                fp_el.text = media_full_path
        if proj_dir:
            for rp_el in m_el.findall("RelativePath"):
                try:
                    rel_p = os.path.relpath(media_full_path, proj_dir)
                    if not rel_p.startswith("."):
                        rel_p = ".\\" + rel_p
                    rp_el.text = rel_p
                except ValueError:
                    rp_el.text = media_full_path
        t_el = m_el.find("Title")
        if t_el is not None and clip_name:
            t_el.text = clip_name
        fk_el = m_el.find("FileKey")
        if fk_el is not None:
            fk_el.text = str(uuid.uuid4())
        imp_el = m_el.find("ImplementationID")
        if imp_el is not None:
            imp_el.text = str(uuid.uuid4())

    if effective_fp and effective_fp.lower().endswith(".mp4") and os.path.exists(effective_fp):
        pmeta = _probe_stream_meta(effective_fp)
        if pmeta["has_video"]:
            vs_ref = m_el.find("VideoStream")
            if vs_ref is not None and vs_ref.attrib.get("ObjectRef") in dst_by_id:
                fr_el = dst_by_id[vs_ref.attrib["ObjectRef"]].find("FrameRect")
                if fr_el is not None:
                    fr_el.text = f"0,0,{pmeta['w']},{pmeta['h']}"
            if (pmeta["w"], pmeta["h"]) != (1920, 1080) and c_el.tag == "VideoClip":
                pol_el = c_el.find("ScaleToFramePolicy")
                if pol_el is None:
                    pol_el = ET.SubElement(c_el, "ScaleToFramePolicy")
                pol_el.text = "1"

    for od_el in src_el.findall(".//OriginalDuration"):
        cur_od = int(od_el.text) if (od_el.text and od_el.text.strip().isdigit()) else 0
        if cur_od < req_ticks or do_path_update:
            od_el.text = str(req_ticks)

    for stream_tag in ("VideoStream", "AudioStream"):
        st_ref = m_el.find(stream_tag)
        if st_ref is not None and st_ref.attrib.get("ObjectRef") in dst_by_id:
            st_el = dst_by_id[st_ref.attrib["ObjectRef"]]
            dur_el = st_el.find("Duration")
            if dur_el is not None:
                cur_d = int(dur_el.text) if (dur_el.text and dur_el.text.strip().isdigit()) else 0
                if cur_d < req_ticks or do_path_update:
                    dur_el.text = str(req_ticks)


def canonicalize_prproj(root, bh_pool):
    for e in root.iter():
        bh = e.attrib.get("BinaryHash")
        if bh and (e.text or "").strip():
            bh_pool[bh] = e.text

    els = list(root)[1:]
    by_key = {}
    for e in els:
        if "ObjectID" in e.attrib:
            by_key[("id", e.attrib["ObjectID"])] = e
        elif "ObjectUID" in e.attrib:
            by_key[("uid", e.attrib["ObjectUID"])] = e

    queue = [("id", "1")]
    seen = {
        ("id", "1"),
        ("id", "0"),
        ("uid", "00000000-0000-0000-0000-000000000000"),
    }
    bfs_order = []
    id_discovery_order = ["1"]

    while queue:
        k = queue.pop(0)
        if k not in by_key:
            raise KeyError(f"Missing referenced object in PremiereData: {k}")
        bfs_order.append(k)
        e = by_key[k]
        for sub in iter_no_pvs(e):
            if "ObjectRef" in sub.attrib:
                nk = ("id", sub.attrib["ObjectRef"])
                if nk not in seen:
                    seen.add(nk)
                    queue.append(nk)
                    id_discovery_order.append(sub.attrib["ObjectRef"])
            if "ObjectURef" in sub.attrib:
                nk = ("uid", sub.attrib["ObjectURef"])
                if nk not in seen:
                    seen.add(nk)
                    queue.append(nk)

    id_map = {"1": "1"}
    next_id = 3
    for old_id in id_discovery_order[1:]:
        id_map[old_id] = str(next_id)
        next_id += 1

    new_root = ET.Element("PremiereData", {"Version": "3"})
    ET.SubElement(new_root, "Project", {"ObjectRef": "1"})

    for k in bfs_order:
        e = by_key[k]
        if k[0] == "id":
            e.attrib["ObjectID"] = id_map[k[1]]
        for sub in iter_no_pvs(e):
            if "ObjectRef" in sub.attrib and sub.attrib["ObjectRef"] in id_map:
                sub.attrib["ObjectRef"] = id_map[sub.attrib["ObjectRef"]]
        new_root.append(e)

    all_node_ids = [
        int(n.findtext("ID"))
        for n in new_root.iter("Node")
        if n.findtext("ID") and n.findtext("ID").strip().isdigit()
    ]
    next_node_id = max(all_node_ids, default=1000000) + 1
    seen_node_ids = set()
    for n in new_root.iter("Node"):
        id_el = n.find("ID")
        if id_el is not None and id_el.text and id_el.text.strip().isdigit():
            val = int(id_el.text.strip())
            if val in seen_node_ids:
                id_el.text = str(next_node_id)
                seen_node_ids.add(next_node_id)
                next_node_id += 1
            else:
                seen_node_ids.add(val)
    proj_next_id_el = new_root.find("./Project[@ObjectID='1']/NextID")
    if proj_next_id_el is not None:
        proj_next_id_el.text = str(max(seen_node_ids, default=1000000) + 1)

    seen_uuids = set()
    for e in new_root.iter():
        for attr in ("ID", "FrameRect", "NodeID", "ClipID", "ActionID"):
            if e.tag == attr and e.text:
                uval = e.text.strip()
                if len(uval) == 36 and uval.count("-") == 4 and uval != "00000000-0000-0000-0000-000000000000":
                    if uval in seen_uuids:
                        new_u = str(uuid.uuid4())
                        e.text = new_u
                        seen_uuids.add(new_u)
                    else:
                        seen_uuids.add(uval)
        if "UUID" in e.attrib:
            uval = e.attrib["UUID"]
            if uval != "00000000-0000-0000-0000-000000000000":
                if uval in seen_uuids:
                    new_u = str(uuid.uuid4())
                    e.attrib["UUID"] = new_u
                    seen_uuids.add(new_u)
                else:
                    seen_uuids.add(uval)

    seen_bh = set()
    for e in new_root.iter():
        bh = e.attrib.get("BinaryHash")
        if bh:
            if bh not in seen_bh:
                if bh not in bh_pool:
                    raise KeyError(f"Missing BinaryHash payload for {bh}")
                e.text = bh_pool[bh]
                seen_bh.add(bh)
            else:
                e.text = None

    return new_root, id_map



