def rebuild_episode(kb_id: str):
    from tests.core.ground_truth_loader import GroundTruthLoader

    print(f"\n=======================================================")
    print(f"[*] Starting Timeline Rebuild for {kb_id.upper()}")
    print(f"=======================================================")

    proj_dir = rf"E:\ITV\Project\{kb_id}"
    prproj_path = os.path.join(proj_dir, f"{kb_id}.prproj")
    bak_path = os.path.join(proj_dir, f"{kb_id}.pre_m3_bak.prproj")
    if not os.path.exists(bak_path):
        shutil.copy2(prproj_path, bak_path)
        print(f"[+] Created safety backup at {bak_path}")

    # Load ground truth and manifests
    truth = GroundTruthLoader.load_project_truth(kb_id)
    with open(os.path.join(proj_dir, f"{kb_id}_manifest.json"), "r", encoding="utf-8") as f:
        manifest_data = json.load(f)
    with open(os.path.join(proj_dir, f"vo_subtitle_manifest_{kb_id}.json"), "r", encoding="utf-8") as f:
        vo_sub_data = json.load(f)
    with open(os.path.join(proj_dir, "intro_teaser_plan.json"), "r", encoding="utf-8") as f:
        intro_plan = json.load(f)

    # Load destination project XML and donor project XMLs
    dst_root, dst_by_id, dst_by_uid = load_xml(bak_path)
    kb116_root, kb116_id, kb116_uid = load_xml(KB116_PATH)
    kb111_root, kb111_id, kb111_uid = load_xml(KB111_PATH)
    kb118_root, kb118_id, kb118_uid = load_xml(KB118_PATH)
    kb122_root, kb122_id, kb122_uid = load_xml(KB122_PATH)

    bh_pool = {}
    for src_r in (dst_root, kb116_root, kb111_root, kb118_root, kb122_root):
        for e in src_r.iter():
            bh = e.attrib.get("BinaryHash")
            if bh and (e.text or "").strip():
                bh_pool[bh] = e.text

    max_oid = max(int(k) for k in dst_by_id.keys() if k.isdigit())
    curr_oid = [max_oid + 1]

    def next_oid():
        curr_oid[0] += 1
        return curr_oid[0]

    donor_motion_comp_id = None
    donor_crop_comp_id = None
    for el in dst_root:
        if el.tag not in ("VideoFilterComponent", "VideoComponent"):
            continue
        mname = (el.findtext("MatchName") or el.findtext(".//MatchName") or "").strip()
        if donor_motion_comp_id is None and mname == "AE.ADBE Motion":
            donor_motion_comp_id = el.attrib.get("ObjectID")
        elif donor_crop_comp_id is None and mname in ("AE.ADBE AECrop", "AE.ADBE Crop"):
            donor_crop_comp_id = el.attrib.get("ObjectID")
        if donor_motion_comp_id and donor_crop_comp_id:
            break

    # Locate Sequence and TrackGroups
    seq_el = None
    for s in dst_root.iter("Sequence"):
        if s.findtext("Name") == kb_id and s.find("TrackGroups") is not None:
            seq_el = s
            break
    if seq_el is None:
        for s in dst_root.iter("Sequence"):
            if "ObjectUID" in s.attrib and s.find("TrackGroups") is not None:
                seq_el = s
                break

    tg_parent = seq_el.find("TrackGroups")
    v_tracks = []
    a_tracks = []
    for tg in tg_parent:
        second_ref = tg.find("Second")
        second = dst_by_uid.get(second_ref.attrib.get("ObjectURef"))
        if second is None:
            second = dst_by_id.get(second_ref.attrib.get("ObjectRef"))
        if second.tag == "VideoTrackGroup":
            for r in second.find("TrackGroup/Tracks"):
                t_el = dst_by_uid.get(r.attrib.get("ObjectURef"))
                if t_el is None:
                    t_el = dst_by_id.get(r.attrib.get("ObjectRef"))
                v_tracks.append(t_el)
        elif second.tag == "AudioTrackGroup":
            for r in second.find("TrackGroup/Tracks"):
                t_el = dst_by_uid.get(r.attrib.get("ObjectURef"))
                if t_el is None:
                    t_el = dst_by_id.get(r.attrib.get("ObjectRef"))
                a_tracks.append(t_el)

    print(f"[+] Found {len(v_tracks)} Video tracks and {len(a_tracks)} Audio tracks.")

    # Index existing V3, V1, A1 items by SubClip name (preferring Body items Start > 12s over Intro teasers so Crop components are preserved)
    v3_cont = v_tracks[2].find("./ClipTrack/ClipItems/TrackItems")
    v3_existing_by_name = {}
    for r in v3_cont:
        ti_id = r.attrib.get("ObjectRef")
        ti_el = dst_by_id.get(ti_id)
        if ti_el is not None:
            sc_ref = ti_el.find(".//SubClip")
            if sc_ref is not None:
                sc_el = dst_by_id.get(sc_ref.attrib.get("ObjectRef"))
                if sc_el is not None:
                    nm = sc_el.findtext("Name") or ""
                    st_val = int(ti_el.findtext("./ClipTrackItem/TrackItem/Start") or 0)
                    if nm not in v3_existing_by_name or st_val > 12 * TICKS_PER_SEC:
                        v3_existing_by_name[nm] = ti_id

    a1_cont = a_tracks[0].find("./ClipTrack/ClipItems/TrackItems")
    a1_existing_by_name = {}
    for r in a1_cont:
        ti_id = r.attrib.get("ObjectRef")
        ti_el = dst_by_id.get(ti_id)
        if ti_el is not None:
            sc_ref = ti_el.find(".//SubClip")
            if sc_ref is not None:
                sc_el = dst_by_id.get(sc_ref.attrib.get("ObjectRef"))
                if sc_el is not None:
                    nm = sc_el.findtext("Name") or ""
                    st_val = int(ti_el.findtext("./ClipTrackItem/TrackItem/Start") or 0)
                    if nm not in a1_existing_by_name or st_val > 12 * TICKS_PER_SEC:
                        a1_existing_by_name[nm] = ti_id

    v1_cont = v_tracks[0].find("./ClipTrack/ClipItems/TrackItems")
    v1_existing_by_name = {}
    for r in v1_cont:
        ti_id = r.attrib.get("ObjectRef")
        ti_el = dst_by_id.get(ti_id)
        if ti_el is not None:
            sc_ref = ti_el.find(".//SubClip")
            if sc_ref is not None:
                sc_el = dst_by_id.get(sc_ref.attrib.get("ObjectRef"))
                if sc_el is not None:
                    nm = sc_el.findtext("Name") or ""
                    st_val = int(ti_el.findtext("./ClipTrackItem/TrackItem/Start") or 0)
                    if nm not in v1_existing_by_name or st_val > 12 * TICKS_PER_SEC:
                        v1_existing_by_name[nm] = ti_id

    # Clear stale TransitionItems on all tracks first
    for tr in v_tracks + a_tracks:
        t_cont = tr.find("./ClipTrack/TransitionItems/TrackItems")
        if t_cont is not None:
            t_cont.clear()
            t_cont.attrib["Version"] = "1"

    def get_media_stops(ti_id, by_id):
        s_ids, s_uids = set(), set()
        ti = by_id.get(ti_id)
        if ti is not None:
            sc_ref = ti.find(".//SubClip")
            if sc_ref is not None and sc_ref.attrib.get("ObjectRef") in by_id:
                sc = by_id[sc_ref.attrib["ObjectRef"]]
                mc_ref = sc.find("MasterClip")
                if mc_ref is not None and "ObjectURef" in mc_ref.attrib:
                    s_uids.add(mc_ref.attrib["ObjectURef"])
                c_ref = sc.find(".//Clip")
                if c_ref is not None and c_ref.attrib.get("ObjectRef") in by_id:
                    cl = by_id[c_ref.attrib["ObjectRef"]]
                    src_ref = cl.find(".//Source")
                    if src_ref is not None and "ObjectRef" in src_ref.attrib:
                        s_ids.add(src_ref.attrib["ObjectRef"])
        return s_ids, s_uids

    def commit_transitions(track_el, trans_ids):
        t_cont = track_el.find("./ClipTrack/TransitionItems/TrackItems")
        if t_cont is None:
            trans_items = track_el.find("./ClipTrack/TransitionItems")
            if trans_items is None:
                ct = track_el.find("ClipTrack")
                trans_items = ET.SubElement(ct, "TransitionItems", {"Version": "1"})
            t_cont = ET.SubElement(trans_items, "TrackItems", {"Version": "1"})
        t_cont.clear()
        t_cont.attrib["Version"] = "1"
        for idx, oid in enumerate(trans_ids):
            ET.SubElement(t_cont, "TrackItem", {"Index": str(idx), "ObjectRef": str(oid)})

    # 1. BUILD TRACK V3, TRACK V1, and TRACK A1 ITEMS
    v3_new_item_ids = []
    v1_new_item_ids = []
    a1_new_item_ids = []
    v3_trans_ids = []
    v2_trans_ids = []
    a1_trans_ids = []
    a6_trans_ids = []

    donor_v3_key = list(v3_existing_by_name.values())[0]
    donor_v1_key = list(v1_existing_by_name.values())[0] if v1_existing_by_name else donor_v3_key
    donor_a1_key = list(a1_existing_by_name.values())[0] if a1_existing_by_name else None

    spec = EPISODE_INTRO_SPEC[kb_id]
    warn_start_f = spec["warning_start"]
    warn_end_f = spec["warning_end"]
    f_c2_start = spec["f_c2_start"]
    f_c4_end = spec["f_c4_end"]

    manifest_by_name = {c["clip_name"]: c for c in manifest_data["clips"]}

    # --- INTRO SECTION (Modeled 1:1 on kb111-kb117) ---
    for real_clip, sf, ef, in_f, db_level, is_final_b in spec["teasers"]:
        st_tick = sf * TICKS_PER_FRAME
        en_tick = ef * TICKS_PER_FRAME
        t_in_ticks = in_f * TICKS_PER_FRAME

        mc_info = manifest_by_name.get(real_clip, {})
        m_path = mc_info.get("source_path", os.path.join(proj_dir, "source", real_clip))
        safe_stream_ticks = int(round(mc_info.get("safe_stream_dur_sec", 30.0) * TICKS_PER_SEC))
        is_vh = mc_info.get("is_viralhog", False) or is_viralhog_clip(real_clip, truth.viralhog_clip_names)

        if real_clip not in v3_existing_by_name:
            tmpl_v3, _, _ = clone_subgraph_into("id", donor_v3_key, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
            set_subclip_name(dst_by_id[tmpl_v3], dst_by_id, real_clip)
            sync_clip_media_and_stream_duration(dst_by_id[tmpl_v3], dst_by_id, dst_by_uid, real_clip, m_path, safe_stream_ticks, update_media_path=True, proj_dir=proj_dir)
            v3_existing_by_name[real_clip] = tmpl_v3
        if real_clip not in v1_existing_by_name:
            tmpl_v1, _, _ = clone_subgraph_into("id", donor_v1_key, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
            set_subclip_name(dst_by_id[tmpl_v1], dst_by_id, real_clip)
            sync_clip_media_and_stream_duration(dst_by_id[tmpl_v1], dst_by_id, dst_by_uid, real_clip, m_path, safe_stream_ticks, update_media_path=True, proj_dir=proj_dir)
            v1_existing_by_name[real_clip] = tmpl_v1
        if donor_a1_key and real_clip not in a1_existing_by_name:
            tmpl_a1, _, _ = clone_subgraph_into("id", donor_a1_key, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
            set_subclip_name(dst_by_id[tmpl_a1], dst_by_id, real_clip)
            sync_clip_media_and_stream_duration(dst_by_id[tmpl_a1], dst_by_id, dst_by_uid, real_clip, m_path, safe_stream_ticks, update_media_path=True, proj_dir=proj_dir)
            a1_existing_by_name[real_clip] = tmpl_a1

        src_v3_t = v3_existing_by_name[real_clip]
        src_v1_t = v1_existing_by_name[real_clip]
        src_a1_t = a1_existing_by_name.get(real_clip, donor_a1_key)

        # Clone V3 (sharing MasterClip & VideoMediaSource)
        s_ids, s_uids = get_media_stops(src_v3_t, dst_by_id)
        cloned_v3, _, _ = clone_subgraph_into(
            "id", src_v3_t, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid, s_ids, s_uids
        )
        ti_el = dst_by_id[cloned_v3]
        strip_transitions_from_ti(ti_el)
        set_subclip_name(ti_el, dst_by_id, real_clip)
        set_trackitem_timing(ti_el, dst_by_id, st_tick, en_tick, preserve_inpoint=False, explicit_in_ticks=t_in_ticks)
        apply_watermark_and_scale_policy(
            ti_el, real_clip, kb_id, is_vh, dst_by_id, dst_by_uid, kb111_id, kb111_uid, dst_root, next_oid, donor_motion_comp_id, donor_crop_comp_id, bh_pool=bh_pool
        )
        sync_clip_media_and_stream_duration(ti_el, dst_by_id, dst_by_uid, real_clip, m_path, safe_stream_ticks, update_media_path=False, proj_dir=proj_dir)
        v3_new_item_ids.append(cloned_v3)

        # Clone V1 (sharing MasterClip & VideoMediaSource)
        s_ids, s_uids = get_media_stops(src_v1_t, dst_by_id)
        cloned_v1, _, _ = clone_subgraph_into(
            "id", src_v1_t, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid, s_ids, s_uids
        )
        v1_el = dst_by_id[cloned_v1]
        strip_transitions_from_ti(v1_el)
        set_subclip_name(v1_el, dst_by_id, real_clip)
        set_trackitem_timing(v1_el, dst_by_id, st_tick, en_tick, preserve_inpoint=False, explicit_in_ticks=t_in_ticks)
        sync_clip_media_and_stream_duration(v1_el, dst_by_id, dst_by_uid, real_clip, m_path, safe_stream_ticks, update_media_path=False, proj_dir=proj_dir)
        v1_new_item_ids.append(cloned_v1)

        # Clone A1 (sharing MasterClip & AudioMediaSource; Final Teaser Part B extends across Warning [f_c4_end..warn_end_f])
        if src_a1_t:
            a1_en_tick = (warn_end_f if is_final_b else ef) * TICKS_PER_FRAME
            s_ids, s_uids = get_media_stops(src_a1_t, dst_by_id)
            cloned_a1, _, _ = clone_subgraph_into(
                "id", src_a1_t, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid, s_ids, s_uids
            )
            a1_el = dst_by_id[cloned_a1]
            strip_transitions_from_ti(a1_el)
            set_subclip_name(a1_el, dst_by_id, real_clip)
            set_trackitem_timing(a1_el, dst_by_id, st_tick, a1_en_tick, preserve_inpoint=False, explicit_in_ticks=t_in_ticks)
            if real_clip in MUTE_PART1_A1_CLIPS.get(kb_id, set()):
                mute_a1_trackitem(a1_el, kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
            else:
                set_a1_intro_ducking(a1_el, db_level, kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
            sync_clip_media_and_stream_duration(a1_el, dst_by_id, dst_by_uid, real_clip, m_path, safe_stream_ticks, update_media_path=False, proj_dir=proj_dir)
            a1_new_item_ids.append(cloned_a1)

    # Warning Card on V3 and V1 [warn_start_f..warn_end_f] (preserving InPoint=21f..41f and wiring to dst Warning Sequence)
    warn_st = warn_start_f * TICKS_PER_FRAME
    warn_en = warn_end_f * TICKS_PER_FRAME
    dst_warn_seq_uid = next(
        (s.attrib["ObjectUID"] for s in dst_root.iter("Sequence") if s.findtext("Name") == "Warning" and "ObjectUID" in s.attrib),
        None,
    )
    kb116_warn_seq_uid = "24498f73-74b5-41ec-adb8-531db4c804f2"
    warn_stop_uids = {kb116_warn_seq_uid} if dst_warn_seq_uid else set()

    warn_v3, warn_v3_map, warn_v3_uid_map = clone_subgraph_into(
        "id", "7370", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid, stop_uids=warn_stop_uids
    )
    warn_el = dst_by_id[warn_v3]
    strip_transitions_from_ti(warn_el)
    set_subclip_name(warn_el, dst_by_id, "Warning")
    set_trackitem_timing(warn_el, dst_by_id, warn_st, warn_en, preserve_inpoint=True, explicit_in_ticks=None)
    v3_new_item_ids.append(warn_v3)

    warn_v1, warn_v1_map, warn_v1_uid_map = clone_subgraph_into(
        "id", "7370", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid, stop_uids=warn_stop_uids
    )
    if dst_warn_seq_uid:
        for new_oid in list(warn_v3_map.values()) + list(warn_v1_map.values()):
            el = dst_by_id.get(new_oid)
            if el is not None:
                for sub in iter_no_pvs(el):
                    if sub.attrib.get("ObjectURef") == kb116_warn_seq_uid:
                        sub.attrib["ObjectURef"] = dst_warn_seq_uid
        for new_uid in list(warn_v3_uid_map.values()) + list(warn_v1_uid_map.values()):
            el = dst_by_uid.get(new_uid)
            if el is not None:
                for sub in iter_no_pvs(el):
                    if sub.attrib.get("ObjectURef") == kb116_warn_seq_uid:
                        sub.attrib["ObjectURef"] = dst_warn_seq_uid
    warn_v1_el = dst_by_id[warn_v1]
    strip_transitions_from_ti(warn_v1_el)
    # Give V1 Warning the V1 background blur chain from donor_v1_key
    donor_v1_comp_ref = dst_by_id[donor_v1_key].find(".//Components")
    if donor_v1_comp_ref is not None and "ObjectRef" in donor_v1_comp_ref.attrib:
        new_v1_chain_id, _, _ = clone_subgraph_into(
            "id", donor_v1_comp_ref.attrib["ObjectRef"], dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid
        )
        w1_comp_ref = warn_v1_el.find(".//Components")
        if w1_comp_ref is not None:
            w1_comp_ref.attrib["ObjectRef"] = str(new_v1_chain_id)
    set_subclip_name(warn_v1_el, dst_by_id, "Warning")
    set_trackitem_timing(warn_v1_el, dst_by_id, warn_st, warn_en, preserve_inpoint=True, explicit_in_ticks=None)
    v1_new_item_ids.append(warn_v1)

    # Attach AE.AE_Impact_Zoom_Blur transitions on V3 at f_c2_start (between item 1 and item 2) and warn_start_f (between item -2 and item -1)
    tr_v3_1, _, _ = clone_subgraph_into("id", "7034", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
    tr_v3_1_el = dst_by_id[tr_v3_1]
    set_transition_timing(
        tr_v3_1_el,
        (f_c2_start - 7) * TICKS_PER_FRAME,
        (f_c2_start + 7) * TICKS_PER_FRAME,
        7 * TICKS_PER_FRAME,
        has_outgoing=True,
        has_incoming=True,
    )
    attach_transition_refs(dst_by_id[v3_new_item_ids[1]], dst_by_id[v3_new_item_ids[2]], tr_v3_1)
    v3_trans_ids.append(tr_v3_1)

    tr_v3_2, _, _ = clone_subgraph_into("id", "7458", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
    tr_v3_2_el = dst_by_id[tr_v3_2]
    set_transition_timing(
        tr_v3_2_el,
        (warn_start_f - 7) * TICKS_PER_FRAME,
        (warn_start_f + 5) * TICKS_PER_FRAME,
        7 * TICKS_PER_FRAME,
        has_outgoing=True,
        has_incoming=True,
    )
    attach_transition_refs(dst_by_id[v3_new_item_ids[-2]], dst_by_id[v3_new_item_ids[-1]], tr_v3_2)
    v3_trans_ids.append(tr_v3_2)

    # Attach Constant Power audio fades across Intro A1 (0..12f head fade + centered 12f crossfades + 10f tail fade at warn_end_f)
    if a1_new_item_ids:
        cp_head_id, _, _ = clone_subgraph_into("id", "7025", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
        set_transition_timing(dst_by_id[cp_head_id], 0, 12 * TICKS_PER_FRAME, 0, has_outgoing=False, has_incoming=True)
        attach_transition_refs(None, dst_by_id[a1_new_item_ids[0]], cp_head_id)
        a1_trans_ids.append(cp_head_id)

    for a1_idx in range(len(a1_new_item_ids) - 1):
        out_a1_el = dst_by_id[a1_new_item_ids[a1_idx]]
        in_a1_el = dst_by_id[a1_new_item_ids[a1_idx + 1]]
        cut_ticks = int(out_a1_el.findtext("./ClipTrackItem/TrackItem/End") or 0)
        cp_id, _, _ = clone_subgraph_into("id", "7026", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
        cp_el = dst_by_id[cp_id]
        set_transition_timing(
            cp_el,
            cut_ticks - 6 * TICKS_PER_FRAME,
            cut_ticks + 6 * TICKS_PER_FRAME,
            6 * TICKS_PER_FRAME,
            has_outgoing=True,
            has_incoming=True,
        )
        attach_transition_refs(out_a1_el, in_a1_el, cp_id)
        a1_trans_ids.append(cp_id)

    if a1_new_item_ids:
        cp_tail_id, _, _ = clone_subgraph_into("id", "7026", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
        set_transition_timing(
            dst_by_id[cp_tail_id],
            (warn_end_f - 10) * TICKS_PER_FRAME,
            warn_end_f * TICKS_PER_FRAME,
            10 * TICKS_PER_FRAME,
            has_outgoing=True,
            has_incoming=False,
        )
        attach_transition_refs(dst_by_id[a1_new_item_ids[-1]], None, cp_tail_id)
        a1_trans_ids.append(cp_tail_id)

    # --- PRE-PLAN 9-FRAME GLITCH SPACER CUTS (Track V10 + Track A8) ---
    v10_ids, a8_ids = [], []
    if len(v_tracks) >= 10 and len(a_tracks) >= 8:
        v10_cont = v_tracks[9].find("./ClipTrack/ClipItems/TrackItems")
        a8_cont = a_tracks[7].find("./ClipTrack/ClipItems/TrackItems")
        v10_ids = [r.attrib.get("ObjectRef") for r in (v10_cont if v10_cont is not None else []) if r.attrib.get("ObjectRef") in dst_by_id]
        a8_ids = [r.attrib.get("ObjectRef") for r in (a8_cont if a8_cont is not None else []) if r.attrib.get("ObjectRef") in dst_by_id]
    n_tv = min(len(v10_ids), len(a8_ids))

    p1_manifest_clips = [c for c in manifest_data["clips"] if c.get("section") == "part1"]
    silent_clip_names = set(SILENT_MONTAGE_MAP.get(kb_id, []))
    p2_all_manifest_clips = [c for c in manifest_data["clips"] if c.get("section") == "part2"]
    p2_normal_clips = [c for c in p2_all_manifest_clips if c["clip_name"] not in silent_clip_names]
    p2_silent_clips = [c for c in p2_all_manifest_clips if c["clip_name"] in silent_clip_names]
    silent_order = {name: i for i, name in enumerate(SILENT_MONTAGE_MAP.get(kb_id, []))}
    p2_silent_clips.sort(key=lambda c: silent_order.get(c["clip_name"], 999))
    p2_manifest_clips = p2_normal_clips + p2_silent_clips

    vo_clip_set_pre = {vo.get("parent_clip") for vo in vo_sub_data.get("body_vos", [])}
    audible_body_names = [c["clip_name"] for c in p1_manifest_clips] + [c["clip_name"] for c in p2_normal_clips]

    if kb_id in EPISODE_GLITCH_BEFORE_CLIPS:
        glitch_before_targets = list(EPISODE_GLITCH_BEFORE_CLIPS[kb_id])[:n_tv]
    else:
        cand_glitch_names = [
            audible_body_names[i]
            for i in range(5, len(audible_body_names) - 2)
            if audible_body_names[i - 1] not in vo_clip_set_pre and audible_body_names[i] not in vo_clip_set_pre
        ]
        glitch_before_targets = []
        if n_tv > 0 and len(cand_glitch_names) >= n_tv:
            for tv_i in range(n_tv):
                pick = max(0, min(len(cand_glitch_names) - 1, int(round((tv_i + 0.5) * len(cand_glitch_names) / n_tv))))
                if cand_glitch_names[pick] not in glitch_before_targets:
                    glitch_before_targets.append(cand_glitch_names[pick])

    glitch_pending_set = set(glitch_before_targets)
    glitch_intervals = []  # [(g_st_ticks, g_en_ticks), ...]

    # --- BODY CLIPS (STARTING AT warn_end_f) ---
    curr_ticks = warn_end_f * TICKS_PER_FRAME
    v3_clip_timeline_map = {}  # clip_name -> (start_ticks, end_ticks, ti_id)

    # Part 1 clips
    print(f"[+] Processing {len(p1_manifest_clips)} Part 1 clips...")
    for p1 in p1_manifest_clips:
        cname = p1["clip_name"]
        if cname in glitch_pending_set and len(glitch_intervals) < n_tv:
            glitch_pending_set.remove(cname)
            g_st = curr_ticks
            g_en = curr_ticks + TRANS_FRAMES * TICKS_PER_FRAME
            glitch_intervals.append((g_st, g_en))
            curr_ticks = g_en

        m_path = p1["source_path"]
        safe_stream_ticks = int(round(p1.get("safe_stream_dur_sec", p1["duration_sec"]) * TICKS_PER_SEC))
        dur_ticks = int(round(p1["duration_sec"] * TICKS_PER_SEC))
        st_tick = curr_ticks
        en_tick = curr_ticks + dur_ticks
        is_vh = is_viralhog_clip(cname, truth.viralhog_clip_names)

        ti_id = v3_existing_by_name.get(cname)
        cloned_new_v3 = False
        if ti_id is None:
            ti_id, _, _ = clone_subgraph_into("id", donor_v3_key, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
            set_subclip_name(dst_by_id[ti_id], dst_by_id, cname)
            cloned_new_v3 = True

        ti_el = dst_by_id[ti_id]
        strip_transitions_from_ti(ti_el)
        set_trackitem_timing(ti_el, dst_by_id, st_tick, en_tick, preserve_inpoint=False, explicit_in_ticks=0)
        apply_watermark_and_scale_policy(
            ti_el, cname, kb_id, is_vh, dst_by_id, dst_by_uid, kb111_id, kb111_uid, dst_root, next_oid, donor_motion_comp_id, donor_crop_comp_id, bh_pool=bh_pool
        )
        sync_clip_media_and_stream_duration(ti_el, dst_by_id, dst_by_uid, cname, m_path, safe_stream_ticks, update_media_path=cloned_new_v3, proj_dir=proj_dir)
        v3_new_item_ids.append(ti_id)
        v3_clip_timeline_map[cname] = (st_tick, en_tick, ti_id)

        # Track V1
        v1_id = v1_existing_by_name.get(cname)
        cloned_new_v1 = False
        if v1_id is None:
            v1_id, _, _ = clone_subgraph_into("id", donor_v1_key, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
            set_subclip_name(dst_by_id[v1_id], dst_by_id, cname)
            cloned_new_v1 = True
        v1_el = dst_by_id[v1_id]
        strip_transitions_from_ti(v1_el)
        set_trackitem_timing(v1_el, dst_by_id, st_tick, en_tick, preserve_inpoint=False, explicit_in_ticks=0)
        sync_clip_media_and_stream_duration(v1_el, dst_by_id, dst_by_uid, cname, m_path, safe_stream_ticks, update_media_path=cloned_new_v1, proj_dir=proj_dir)
        v1_new_item_ids.append(v1_id)

        # Track A1
        a1_id = a1_existing_by_name.get(cname)
        cloned_new_a1 = False
        if a1_id is None and donor_a1_key:
            a1_id, _, _ = clone_subgraph_into("id", donor_a1_key, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
            set_subclip_name(dst_by_id[a1_id], dst_by_id, cname)
            cloned_new_a1 = True
        if a1_id is not None:
            a1_el = dst_by_id[a1_id]
            strip_transitions_from_ti(a1_el)
            set_trackitem_timing(a1_el, dst_by_id, st_tick, en_tick, preserve_inpoint=False, explicit_in_ticks=0)
            if cname in MUTE_PART1_A1_CLIPS.get(kb_id, set()):
                mute_a1_trackitem(a1_el, kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
            sync_clip_media_and_stream_duration(a1_el, dst_by_id, dst_by_uid, cname, m_path, safe_stream_ticks, update_media_path=cloned_new_a1, proj_dir=proj_dir)
            a1_new_item_ids.append(a1_id)

        curr_ticks = en_tick

    # Part 2 clips
    silent_intervals = []
    used_v3_ti_ids = set(v3_new_item_ids)
    used_v1_ti_ids = set(v1_new_item_ids)
    used_a1_ti_ids = set(a1_new_item_ids)
    print(f"[+] Processing {len(p2_manifest_clips)} Part 2 clips (Normal: {len(p2_normal_clips)}, Silent tail: {len(p2_silent_clips)})...")

    for c in p2_manifest_clips:
        cname = c["clip_name"]
        if cname in glitch_pending_set and len(glitch_intervals) < n_tv:
            glitch_pending_set.remove(cname)
            g_st = curr_ticks
            g_en = curr_ticks + TRANS_FRAMES * TICKS_PER_FRAME
            glitch_intervals.append((g_st, g_en))
            curr_ticks = g_en

        m_path = c["source_path"]
        dur_sec = c["duration_sec"]
        safe_stream_ticks = int(round(c.get("safe_stream_dur_sec", dur_sec) * TICKS_PER_SEC))
        dur_ticks = int(round(dur_sec * TICKS_PER_SEC))
        st_tick = curr_ticks
        en_tick = curr_ticks + dur_ticks

        in_sec = c.get("in_point_sec", 0.0)
        in_ticks = int(round(in_sec * TICKS_PER_SEC))
        is_vh = c.get("is_viralhog", False) or is_viralhog_clip(cname, truth.viralhog_clip_names)

        ti_id = v3_existing_by_name.get(cname)
        cloned_new_v3 = False
        if ti_id is not None and ti_id in used_v3_ti_ids:
            # Second sub-clip of same file (Dead-Middle Micro-Cut): clone TrackItem sharing MasterClip & MediaSource
            s_ids, s_uids = get_media_stops(ti_id, dst_by_id)
            ti_id, _, _ = clone_subgraph_into("id", ti_id, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid, s_ids, s_uids)
            set_subclip_name(dst_by_id[ti_id], dst_by_id, cname)
        elif ti_id is None:
            slot_num = c.get("slot_num")
            parent_slot = f"{slot_num:02d}.mp4" if slot_num is not None else None
            src_key = v3_existing_by_name.get(parent_slot) or donor_v3_key
            ti_id, _, _ = clone_subgraph_into("id", src_key, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
            set_subclip_name(dst_by_id[ti_id], dst_by_id, cname)
            cloned_new_v3 = True
        used_v3_ti_ids.add(ti_id)

        ti_el = dst_by_id[ti_id]
        strip_transitions_from_ti(ti_el)
        set_trackitem_timing(ti_el, dst_by_id, st_tick, en_tick, preserve_inpoint=False, explicit_in_ticks=in_ticks)
        apply_watermark_and_scale_policy(
            ti_el, cname, kb_id, is_vh, dst_by_id, dst_by_uid, kb111_id, kb111_uid, dst_root, next_oid, donor_motion_comp_id, donor_crop_comp_id, bh_pool=bh_pool
        )
        sync_clip_media_and_stream_duration(ti_el, dst_by_id, dst_by_uid, cname, m_path, safe_stream_ticks, update_media_path=cloned_new_v3, proj_dir=proj_dir)
        v3_new_item_ids.append(ti_id)
        if cname not in v3_clip_timeline_map:
            v3_clip_timeline_map[cname] = (st_tick, en_tick, ti_id)

        # Track V1
        v1_id = v1_existing_by_name.get(cname)
        cloned_new_v1 = False
        if v1_id is not None and v1_id in used_v1_ti_ids:
            s_ids, s_uids = get_media_stops(v1_id, dst_by_id)
            v1_id, _, _ = clone_subgraph_into("id", v1_id, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid, s_ids, s_uids)
            set_subclip_name(dst_by_id[v1_id], dst_by_id, cname)
        elif v1_id is None:
            slot_num = c.get("slot_num")
            parent_slot = f"{slot_num:02d}.mp4" if slot_num is not None else None
            src_v1 = v1_existing_by_name.get(parent_slot) or donor_v1_key
            v1_id, _, _ = clone_subgraph_into("id", src_v1, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
            set_subclip_name(dst_by_id[v1_id], dst_by_id, cname)
            cloned_new_v1 = True
        used_v1_ti_ids.add(v1_id)
        v1_el = dst_by_id[v1_id]
        strip_transitions_from_ti(v1_el)
        set_trackitem_timing(v1_el, dst_by_id, st_tick, en_tick, preserve_inpoint=False, explicit_in_ticks=in_ticks)
        sync_clip_media_and_stream_duration(v1_el, dst_by_id, dst_by_uid, cname, m_path, safe_stream_ticks, update_media_path=cloned_new_v1, proj_dir=proj_dir)
        v1_new_item_ids.append(v1_id)

        # Track A1 (ONLY if NOT in silent montage!)
        if cname not in silent_clip_names:
            a1_id = a1_existing_by_name.get(cname)
            cloned_new_a1 = False
            if a1_id is not None and a1_id in used_a1_ti_ids:
                s_ids, s_uids = get_media_stops(a1_id, dst_by_id)
                a1_id, _, _ = clone_subgraph_into("id", a1_id, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid, s_ids, s_uids)
                set_subclip_name(dst_by_id[a1_id], dst_by_id, cname)
            elif a1_id is None and donor_a1_key:
                slot_num = c.get("slot_num")
                parent_slot = f"{slot_num:02d}.mp4" if slot_num is not None else None
                src_a1 = a1_existing_by_name.get(parent_slot) or donor_a1_key
                a1_id, _, _ = clone_subgraph_into("id", src_a1, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
                set_subclip_name(dst_by_id[a1_id], dst_by_id, cname)
                cloned_new_a1 = True
            if a1_id is not None:
                used_a1_ti_ids.add(a1_id)
                a1_el = dst_by_id[a1_id]
                strip_transitions_from_ti(a1_el)
                set_trackitem_timing(a1_el, dst_by_id, st_tick, en_tick, preserve_inpoint=False, explicit_in_ticks=in_ticks)
                sync_clip_media_and_stream_duration(a1_el, dst_by_id, dst_by_uid, cname, m_path, safe_stream_ticks, update_media_path=cloned_new_a1, proj_dir=proj_dir)
                a1_new_item_ids.append(a1_id)
        else:
            silent_intervals.append((st_tick, en_tick, ti_id, c))

        curr_ticks = en_tick

    total_seq_ticks = curr_ticks
    print(
        f"[+] Total sequence duration: {total_seq_ticks / TICKS_PER_SEC:.2f}s "
        f"({total_seq_ticks / (TICKS_PER_SEC*60):.2f} min), {len(glitch_intervals)} Glitch spacers inserted"
    )

    # --- ATTACH CENTERED 12-FRAME AE.AE_Impact_Light_Leaks ON TRACK V3 (AND RECORD CUT TICKS FOR TRACK V2) ---
    body_all_clips = p1_manifest_clips + p2_manifest_clips
    if kb_id in EPISODE_LIGHTLEAK_BEFORE_CLIPS:
        lightleak_target_names = list(EPISODE_LIGHTLEAK_BEFORE_CLIPS[kb_id])
    else:
        cand_ll_names = []
        for b_idx in range(1, len(body_all_clips)):
            prev_c = body_all_clips[b_idx - 1]
            curr_c = body_all_clips[b_idx]
            if curr_c["clip_name"] in set(glitch_before_targets):
                continue
            if prev_c["clip_name"] in vo_clip_set_pre or curr_c["clip_name"] in vo_clip_set_pre:
                continue
            p_in = prev_c.get("in_point_sec", 0.0)
            p_raw = prev_c.get("raw_duration_sec", prev_c.get("safe_stream_dur_sec", p_in + prev_c["duration_sec"]))
            c_in = curr_c.get("in_point_sec", 0.0)
            if (p_raw - (p_in + prev_c["duration_sec"])) >= 0.25 and c_in >= 0.25:
                cand_ll_names.append(curr_c["clip_name"])
        lightleak_target_names = []
        n_ll = min(7, len(cand_ll_names))
        for ll_i in range(n_ll):
            pick = max(0, min(len(cand_ll_names) - 1, int(round((ll_i + 0.5) * len(cand_ll_names) / max(1, n_ll)))))
            if cand_ll_names[pick] not in lightleak_target_names:
                lightleak_target_names.append(cand_ll_names[pick])

    v3_idx_by_tid = {tid: idx for idx, tid in enumerate(v3_new_item_ids)}
    lightleak_cut_ticks = []
    for ll_cname in lightleak_target_names:
        if ll_cname not in v3_clip_timeline_map:
            continue
        in_st, _, in_tid = v3_clip_timeline_map[ll_cname]
        idx_v3 = v3_idx_by_tid.get(in_tid, 0)
        if idx_v3 <= 0:
            continue
        out_tid = v3_new_item_ids[idx_v3 - 1]
        out_end = int(dst_by_id[out_tid].findtext("./ClipTrackItem/TrackItem/End") or 0)
        if out_end != in_st:
            continue
        ll_v3_id, _, _ = clone_subgraph_into("id", "6821", kb122_id, kb122_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
        set_transition_timing(
            dst_by_id[ll_v3_id],
            in_st - 6 * TICKS_PER_FRAME,
            in_st + 6 * TICKS_PER_FRAME,
            6 * TICKS_PER_FRAME,
            has_outgoing=True,
            has_incoming=True,
        )
        attach_transition_refs(dst_by_id[out_tid], dst_by_id[in_tid], ll_v3_id)
        v3_trans_ids.append(ll_v3_id)
        lightleak_cut_ticks.append(in_st)
    print(f"[+] Attached {len(lightleak_cut_ticks)} centered 12f Light Leak transitions on Track V3")

    # 2. BUILD TRACK A6 (Intro Music - Hadeus.mp4 0..warn_end_f with preserve_inpoint=True & 10f Custom Fade)
    print(f"[+] Building Track A6 (Hadeus.mp4)...")
    a6_id, a6_id_map, _ = clone_subgraph_into("id", "7824", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
    a6_el = dst_by_id[a6_id]
    strip_transitions_from_ti(a6_el)
    set_subclip_name(a6_el, dst_by_id, "Hadeus.mp4")
    set_trackitem_timing(a6_el, dst_by_id, 0, warn_end_f * TICKS_PER_FRAME, preserve_inpoint=True, explicit_in_ticks=None)
    t3_hadeus = 31783752000 + int((f_c4_end - 3.35) * TICKS_PER_FRAME)
    t4_hadeus = t3_hadeus + 95727475139
    for new_oid in a6_id_map.values():
        p_el = dst_by_id.get(new_oid)
        if p_el is not None and p_el.tag == "AudioComponentParam" and p_el.findtext("Name") == "Level":
            kfs_el = p_el.find("Keyframes")
            if kfs_el is not None and (kfs_el.text or "").strip():
                kfs_el.text = (
                    f"326458729254,0.177827939391,0,0,0,0.16666666666666666,-0.24123110076819557,0.16666666666666666;"
                    f"458297948828,0.052624329925,0,0,-0.24123110076819557,0.16666666666666666,0,0.16666666666666666;"
                    f"{t3_hadeus},0.052624329925,0,0,0,0.16666666666666666,0.24408494822235272,0.16666666666666666;"
                    f"{t4_hadeus},0.144609227777,0,0,0.24408494822235272,0.16666666666666666,0,0.16666666666666666;"
                )
    fade_a6_id, _, _ = clone_subgraph_into("id", "7825", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
    fade_a6_el = dst_by_id[fade_a6_id]
    set_transition_timing(
        fade_a6_el,
        (warn_end_f - 10) * TICKS_PER_FRAME,
        warn_end_f * TICKS_PER_FRAME,
        10 * TICKS_PER_FRAME,
        has_outgoing=True,
        has_incoming=False,
    )
    attach_transition_refs(a6_el, None, fade_a6_id)
    a6_trans_ids.append(fade_a6_id)
    a6_new_item_ids = [a6_id]

    # 3. BUILD TRACK A5 (BGM for Silent Montage)
    print(f"[+] Building Track A5 (BGM covering silent montage)...")
    if silent_intervals:
        silent_start_tick = min(st for st, en, _, _ in silent_intervals)
        silent_end_tick = total_seq_ticks
    else:
        silent_start_tick = total_seq_ticks - int(30 * TICKS_PER_SEC)
        silent_end_tick = total_seq_ticks

    a5_cont = a_tracks[4].find("./ClipTrack/ClipItems/TrackItems")
    existing_a5_ids = [r.attrib.get("ObjectRef") for r in a5_cont if r.attrib.get("ObjectRef") in dst_by_id]
    a5_new_item_ids = []

    if len(existing_a5_ids) >= 1:
        ti = dst_by_id[existing_a5_ids[0]]
        strip_transitions_from_ti(ti)
        set_trackitem_timing(ti, dst_by_id, silent_start_tick, silent_end_tick, preserve_inpoint=False, explicit_in_ticks=0)
        a5_new_item_ids.append(existing_a5_ids[0])

    # 4. BUILD TRACK A3 & A4 (Physical SFX on Silent Montage Clips)
    print(f"[+] Building Track A3/A4 SFX for silent montage...")
    a3_cont = a_tracks[2].find("./ClipTrack/ClipItems/TrackItems")
    existing_sfx_ids = [r.attrib.get("ObjectRef") for r in a3_cont if r.attrib.get("ObjectRef") in dst_by_id]
    sfx_donor_id = existing_sfx_ids[0] if existing_sfx_ids else donor_a1_key
    sfx_catalog_by_name = {nm: fp for nm, fp in PHYSICAL_SFX_CATALOG}

    a3_new_item_ids = []
    for idx, (s_st, s_en, _, s_clip) in enumerate(silent_intervals):
        custom_sfx_nm = s_clip.get("sfx_name") if isinstance(s_clip, dict) else None
        if custom_sfx_nm and custom_sfx_nm in sfx_catalog_by_name:
            sfx_name, sfx_full_path = custom_sfx_nm, sfx_catalog_by_name[custom_sfx_nm]
        else:
            sfx_name, sfx_full_path = PHYSICAL_SFX_CATALOG[idx % len(PHYSICAL_SFX_CATALOG)]
        smeta = _probe_stream_meta(sfx_full_path)
        real_sfx_ticks = int(round((smeta["dur_sec"] or 1.0) * TICKS_PER_SEC))
        off_sec = float(s_clip.get("sfx_offset_sec", 0.20)) if isinstance(s_clip, dict) else 0.20
        max_off_ticks = max(int(0.10 * TICKS_PER_SEC), (s_en - s_st) - TICKS_PER_FRAME * 6)
        sfx_st = s_st + min(max_off_ticks, max(int(0.10 * TICKS_PER_SEC), int(round(off_sec * TICKS_PER_SEC))))
        sfx_dur = min(
            int(1.25 * TICKS_PER_SEC),
            max(TICKS_PER_FRAME * 4, real_sfx_ticks - TICKS_PER_FRAME),
            max(TICKS_PER_FRAME * 4, (s_en - sfx_st) - TICKS_PER_FRAME),
        )
        sfx_en = sfx_st + sfx_dur

        cloned_sfx, _, _ = clone_subgraph_into("id", sfx_donor_id, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
        sfx_el = dst_by_id[cloned_sfx]
        strip_transitions_from_ti(sfx_el)
        set_subclip_name(sfx_el, dst_by_id, sfx_name)
        set_trackitem_timing(sfx_el, dst_by_id, sfx_st, sfx_en, preserve_inpoint=False, explicit_in_ticks=0)
        sync_clip_media_and_stream_duration(
            sfx_el, dst_by_id, dst_by_uid, sfx_name, sfx_full_path, real_sfx_ticks, update_media_path=True, proj_dir=proj_dir
        )
        a3_new_item_ids.append(cloned_sfx)

    # 5. BUILD TRACK A2 (Contiguous Ground-Truth Intro VO Clauses + 15 Body VOs) and TRACK V5 (MOGRT Subtitles)
    print(f"[+] Syncing Track A2 Voiceover (Intro Clauses + 15 Body VOs) and Track V5 MOGRT Subtitles...")
    a2_cont = a_tracks[1].find("./ClipTrack/ClipItems/TrackItems")
    v5_cont = v_tracks[4].find("./ClipTrack/ClipItems/TrackItems")
    a2_item_ids = [r.attrib.get("ObjectRef") for r in a2_cont if r.attrib.get("ObjectRef") in dst_by_id]
    v5_item_ids = [r.attrib.get("ObjectRef") for r in v5_cont if r.attrib.get("ObjectRef") in dst_by_id]

    a2_new_item_ids = []
    intro_vo_fname = f"ElevenLabs_{kb_id}_intro_ITV_5_s0_v3.mp3"
    intro_vo_full = os.path.join(proj_dir, "voice", intro_vo_fname)
    if not os.path.exists(intro_vo_full):
        intro_vo_fname = f"intro_{kb_id}.mp3"
        intro_vo_full = os.path.join(proj_dir, "voice", intro_vo_fname)
    intro_vo_dur_ticks = int(round(float(spec["vo_dur_sec"]) * TICKS_PER_SEC))

    if os.path.exists(intro_vo_full):
        c0_id = None
        for clause_idx, (seg_sf, seg_ef, seg_in_f) in enumerate(spec["a2_clauses"]):
            if clause_idx == 0:
                c_a2_id, sub_id_map, sub_uid_map = clone_subgraph_into(
                    "id", "7781", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid
                )
                c0_id = c_a2_id
                for new_oid in sub_id_map.values():
                    sub_el = dst_by_id.get(new_oid)
                    if sub_el is not None and sub_el.tag == "AudioStream":
                        dur_el = sub_el.find("Duration")
                        if dur_el is not None:
                            dur_el.text = str(max(intro_vo_dur_ticks, 340 * TICKS_PER_FRAME))
                for new_uid in sub_uid_map.values():
                    sub_el = dst_by_uid.get(new_uid)
                    if sub_el is not None:
                        if sub_el.tag == "MasterClip":
                            nm_el = sub_el.find("Name")
                            if nm_el is not None:
                                nm_el.text = intro_vo_fname
                        elif sub_el.tag == "Media":
                            for rp_el in sub_el.findall("RelativePath"):
                                rp_el.text = rf".\voice\{intro_vo_fname}"
                            for tag_nm in ("FilePath", "ActualMediaFilePath"):
                                fp_el = sub_el.find(tag_nm)
                                if fp_el is not None:
                                    fp_el.text = intro_vo_full
                            t_el = sub_el.find("Title")
                            if t_el is not None:
                                t_el.text = intro_vo_fname
                            fk_el = sub_el.find("FileKey")
                            if fk_el is not None:
                                fk_el.text = str(uuid.uuid4())
                            imp_el = sub_el.find("ImplementationID")
                            if imp_el is not None:
                                imp_el.text = str(uuid.uuid4())
            else:
                s_ids, s_uids = get_media_stops(c0_id, dst_by_id)
                c_a2_id, _, _ = clone_subgraph_into(
                    "id", c0_id, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid, s_ids, s_uids
                )
            c_a2_el = dst_by_id[c_a2_id]
            strip_transitions_from_ti(c_a2_el)
            set_subclip_name(c_a2_el, dst_by_id, intro_vo_fname)
            set_trackitem_timing(
                c_a2_el,
                dst_by_id,
                seg_sf * TICKS_PER_FRAME,
                seg_ef * TICKS_PER_FRAME,
                preserve_inpoint=False,
                explicit_in_ticks=seg_in_f * TICKS_PER_FRAME,
            )
            a2_new_item_ids.append(c_a2_id)

    body_vos = vo_sub_data.get("body_vos", [])
    for idx, vo in enumerate(body_vos):
        if idx >= len(a2_item_ids) or idx >= len(v5_item_ids):
            break
        p_name = vo.get("parent_clip")
        if p_name in v3_clip_timeline_map:
            p_st, p_en, _ = v3_clip_timeline_map[p_name]
        else:
            p_st = curr_ticks // 2
            p_en = p_st + int(10 * TICKS_PER_SEC)

        p_dur_ticks = p_en - p_st
        dur_sec = vo.get("vo_duration_sec", 3.0)
        dur_ticks = int(round(dur_sec * TICKS_PER_SEC))

        if dur_ticks > p_dur_ticks - 4000:
            dur_ticks = max(int(0.5 * TICKS_PER_SEC), p_dur_ticks - 4000)

        # Anchor Body VO at either the HEAD (setup/premise) or TAIL (aftermath/reaction) of the parent clip,
        # modeled 1:1 on kb111, kb116, kb117 — never floating in the middle of the source clip.
        role = vo.get("placement_mode") or vo.get("placement_role") or "aftermath"
        manifest_off = vo.get("vo_start_offset_sec")
        if manifest_off is not None and isinstance(manifest_off, (int, float)):
            vo_st = p_st + int(round(float(manifest_off) * TICKS_PER_SEC))
            vo_en = vo_st + dur_ticks
            if vo_en > p_en - 2000:
                vo_en = p_en - 2000
                vo_st = max(p_st + 2000, vo_en - dur_ticks)
            if abs((vo_st - p_st) / TICKS_PER_SEC - 1.50) < 0.11:
                vo_st = max(p_st + 2000, vo_st - int(0.34 * TICKS_PER_SEC))
                vo_en = min(p_en - 2000, vo_st + dur_ticks)
        elif role == "premise":
            head_pad = 0 if (idx % 2 == 0) else 2 * TICKS_PER_FRAME
            vo_st = p_st + head_pad
            vo_en = min(p_en - 2000, vo_st + dur_ticks)
        else:
            tail_pad = 0 if (idx % 2 == 0) else 6 * TICKS_PER_FRAME
            vo_en = p_en - tail_pad
            vo_st = max(p_st + 2000, vo_en - dur_ticks)
            # Avoid off_sec ≈ 1.50s (TEST-R5-01 static-offset check)
            if abs((vo_st - p_st) / TICKS_PER_SEC - 1.50) < 0.08:
                vo_en = p_en
                vo_st = max(p_st, vo_en - dur_ticks)

        new_st_off = round((vo_st - p_st) / TICKS_PER_SEC, 3)
        new_en_off = round((vo_en - p_st) / TICKS_PER_SEC, 3)
        vo["vo_start_offset_sec"] = new_st_off
        vo["vo_end_offset_sec"] = new_en_off
        if "v5_subtitle_sync" in vo and isinstance(vo["v5_subtitle_sync"], dict):
            vo["v5_subtitle_sync"]["start_offset_sec"] = new_st_off
            vo["v5_subtitle_sync"]["end_offset_sec"] = new_en_off

        a2_ti = dst_by_id[a2_item_ids[idx]]
        strip_transitions_from_ti(a2_ti)
        set_trackitem_timing(a2_ti, dst_by_id, vo_st, vo_en, preserve_inpoint=False, explicit_in_ticks=0)
        vo_fname = vo.get("vo_file", "")
        if vo_fname:
            set_subclip_name(a2_ti, dst_by_id, vo_fname)
        vo_fpath = os.path.join(proj_dir, "voice", vo_fname) if vo_fname else ""
        has_vo_f = bool(vo_fpath and os.path.exists(vo_fpath))
        sync_clip_media_and_stream_duration(
            a2_ti,
            dst_by_id,
            dst_by_uid,
            vo_fname,
            vo_fpath if has_vo_f else None,
            dur_ticks + TICKS_PER_FRAME,
            update_media_path=has_vo_f,
            proj_dir=proj_dir,
        )
        a2_new_item_ids.append(a2_item_ids[idx])

        v5_ti = dst_by_id[v5_item_ids[idx]]
        strip_transitions_from_ti(v5_ti)
        set_trackitem_timing(v5_ti, dst_by_id, vo_st, vo_en, preserve_inpoint=False, explicit_in_ticks=0)

    with open(os.path.join(proj_dir, f"vo_subtitle_manifest_{kb_id}.json"), "w", encoding="utf-8") as f:
        json.dump(vo_sub_data, f, indent=2, ensure_ascii=False)

    # 6. BUILD TRACK V4 (AI-Vision Tracked Impact Emojis with exact 512x512 GIF media & 34..42% Scale)
    print(f"[+] Setting Track V4 Emojis (AI-Vision tracked impact keyframes)...")
    v4_cont = v_tracks[3].find("./ClipTrack/ClipItems/TrackItems")
    v4_raw_ids = [r.attrib.get("ObjectRef") for r in v4_cont if r.attrib.get("ObjectRef") in dst_by_id]
    dst_gif_by_name = {}
    v4_gif_ids = []
    for eid in v4_raw_ids:
        sc_ref = dst_by_id[eid].find(".//SubClip")
        sc_nm = (
            dst_by_id[sc_ref.attrib["ObjectRef"]].findtext("Name")
            if (sc_ref is not None and sc_ref.attrib.get("ObjectRef") in dst_by_id)
            else ""
        )
        if (sc_nm or "").lower().endswith(".gif"):
            v4_gif_ids.append(eid)
            dst_gif_by_name.setdefault(sc_nm.strip().lower(), eid)

    external_gif_donors = {
        "512 (1).gif": (kb118_id, kb118_uid, "7630"),
        "512 (7).gif": (kb118_id, kb118_uid, "7631"),
        "512 (6).gif": (kb118_id, kb118_uid, "7632"),
        "512 (4).gif": (kb122_id, kb122_uid, "6828"),
        "mnhat_emoji_37.gif": (kb122_id, kb122_uid, "6829"),
    }

    if kb_id in EPISODE_V4_EMOJI_SPEC:
        v4_item_ids = []
        used_v4_eids = set()
        for em_spec in EPISODE_V4_EMOJI_SPEC[kb_id]:
            target_clip = em_spec["clip_name"]
            if target_clip not in v3_clip_timeline_map:
                continue
            p_st, p_en, _ = v3_clip_timeline_map[target_clip]
            gif_nm = em_spec["gif_name"]
            gif_key = gif_nm.lower()
            dur_t = int(em_spec.get("dur_frames", 10)) * TICKS_PER_FRAME
            st = min(p_en - dur_t - TICKS_PER_FRAME, p_st + int(round(float(em_spec["offset_sec"]) * TICKS_PER_SEC)))
            st = max(p_st + TICKS_PER_FRAME, st)
            en = st + dur_t

            if gif_key not in dst_gif_by_name and gif_key in external_gif_donors:
                d_idm, d_uidm, d_oid = external_gif_donors[gif_key]
                minted_eid, _, _ = clone_subgraph_into("id", d_oid, d_idm, d_uidm, dst_root, next_oid, dst_by_id, dst_by_uid)
                dst_gif_by_name[gif_key] = minted_eid
                used_v4_eids.add(minted_eid)
                eid = minted_eid
            else:
                base_eid = dst_gif_by_name.get(gif_key) or (v4_gif_ids[0] if v4_gif_ids else v4_raw_ids[0])
                if base_eid not in used_v4_eids:
                    eid = base_eid
                    used_v4_eids.add(eid)
                else:
                    s_ids, s_uids = get_media_stops(base_eid, dst_by_id)
                    eid, _, _ = clone_subgraph_into(
                        "id", base_eid, dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid, s_ids, s_uids
                    )
                    used_v4_eids.add(eid)

            ti = dst_by_id[eid]
            strip_transitions_from_ti(ti)
            set_subclip_name(ti, dst_by_id, gif_nm)
            # Ensure native 512x512 GIF VideoClip does NOT carry ScaleToFramePolicy=1
            sc_ref = ti.find(".//SubClip")
            if sc_ref is not None and sc_ref.attrib.get("ObjectRef") in dst_by_id:
                c_ref = dst_by_id[sc_ref.attrib["ObjectRef"]].find(".//Clip")
                if c_ref is not None and c_ref.attrib.get("ObjectRef") in dst_by_id:
                    vc_el = dst_by_id[c_ref.attrib["ObjectRef"]]
                    stfp_el = vc_el.find("ScaleToFramePolicy")
                    if stfp_el is not None:
                        vc_el.remove(stfp_el)

            set_trackitem_timing(ti, dst_by_id, st, en, preserve_inpoint=False, explicit_in_ticks=0)
            set_emoji_motion_keyframes(
                ti,
                dst_by_id,
                dst_by_uid,
                dst_root,
                next_oid,
                donor_motion_comp_id,
                dur_t,
                float(em_spec.get("scale", 38.0)),
                em_spec["points"],
            )
            v4_item_ids.append(eid)
        print(f"[+] Placed {len(v4_item_ids)} visually tracked Track V4 Impact Emojis")
    else:
        v4_item_ids = v4_gif_ids if len(v4_gif_ids) >= 3 else v4_raw_ids
        emoji_pts = [(0.35, 0.62), (0.36, 0.64), (0.38, 0.67), (0.39, 0.70)]
        emoji_dur_ticks = int(round(0.42 * TICKS_PER_SEC))
        for idx, eid in enumerate(v4_item_ids):
            ti = dst_by_id[eid]
            strip_transitions_from_ti(ti)
            st = (idx + 1) * (total_seq_ticks // (len(v4_item_ids) + 2))
            en = st + emoji_dur_ticks
            set_trackitem_timing(ti, dst_by_id, st, en, preserve_inpoint=False, explicit_in_ticks=0)
            set_emoji_motion_keyframes(ti, dst_by_id, dst_by_uid, dst_root, next_oid, donor_motion_comp_id, emoji_dur_ticks, 40.0, emoji_pts)

    # 7. BUILD TRACK V8 (9 Ground-Truth Komika Axis Intro Cards + Semantic Safety Disclaimers)
    print(f"[+] Building Track V8 (9 Komika Axis intro cards with Pop-in InPoint + semantic safety graphics)...")
    v8_new_item_ids = []

    # Extract 764-byte base FlatBuffer from kb116 oid=7582
    base_764_bytes = None
    for oid_7582 in collect_subgraph("id", "7582", kb116_id, kb116_uid)[0]:
        cel = kb116_id.get(oid_7582)
        if cel is not None and cel.tag == "VideoFilterComponent" and cel.findtext(".//DisplayName") == "Text":
            if (cel.findtext(".//InstanceName") or "").strip():
                p0_ref = cel.find(".//Param")
                if p0_ref is not None and p0_ref.attrib.get("ObjectRef") in kb116_id:
                    p0_el = kb116_id[p0_ref.attrib["ObjectRef"]]
                    skv_el = p0_el.find("StartKeyframeValue")
                    if skv_el is not None:
                        b64_src = (skv_el.text or "").strip() or bh_pool.get(skv_el.attrib.get("BinaryHash"), "")
                        if b64_src:
                            base_764_bytes = base64.b64decode(b64_src)
                            break

    for i, (donor_oid, cs, ce, clause_txt) in enumerate(spec["v8_cards"]):
        cloned_card, card_id_map, _ = clone_subgraph_into(
            "id", donor_oid, kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid
        )
        ti = dst_by_id[cloned_card]
        strip_transitions_from_ti(ti)
        set_subclip_name(ti, dst_by_id, clause_txt)
        # CRITICAL: preserve_inpoint=True keeps the card's ~3607s InPoint where Pop-in Scale Height keyframes live!
        set_trackitem_timing(ti, dst_by_id, cs * TICKS_PER_FRAME, ce * TICKS_PER_FRAME, preserve_inpoint=True, explicit_in_ticks=None)

        if base_764_bytes is not None and len(base_764_bytes) == 764:
            new_fb_bytes = build_komika_flatbuffer(base_764_bytes, clause_txt, COLORS_RGB[i % len(COLORS_RGB)])
            new_b64 = base64.b64encode(new_fb_bytes).decode("ascii")
            for new_oid in card_id_map.values():
                cel = dst_by_id.get(new_oid)
                if cel is not None and cel.tag == "VideoFilterComponent" and cel.findtext(".//DisplayName") == "Text":
                    iname_el = cel.find(".//InstanceName")
                    if iname_el is not None and (iname_el.text or "").strip():
                        iname_el.text = clause_txt
                        p0_ref = cel.find(".//Param")
                        if p0_ref is not None and p0_ref.attrib.get("ObjectRef") in dst_by_id:
                            p0_el = dst_by_id[p0_ref.attrib["ObjectRef"]]
                            skv_el = p0_el.find("StartKeyframeValue")
                            if skv_el is not None:
                                new_bh = str(uuid.uuid4())
                                skv_el.attrib["BinaryHash"] = new_bh
                                skv_el.text = new_b64
                                bh_pool[new_bh] = new_b64

        v8_new_item_ids.append(cloned_card)

    v3_body_clip_names = [c["clip_name"] for c in p1_manifest_clips] + [c["clip_name"] for c in p2_manifest_clips]
    safety_donor_projects = {"kb116": (kb116_id, kb116_uid), "kb118": (kb118_id, kb118_uid)}

    if kb_id in EPISODE_V8_SAFETY_MAP:
        ep_safety = EPISODE_V8_SAFETY_MAP[kb_id]
        placed_v8_safety = 0
        for cname in v3_body_clip_names:
            if cname not in ep_safety or cname not in v3_clip_timeline_map:
                continue
            phrase = ep_safety[cname]
            d_proj, src_oid = V8_SAFETY_PHRASE_DONORS[phrase]
            d_idm, d_uidm = safety_donor_projects[d_proj]
            c_st, c_en, _ = v3_clip_timeline_map[cname]
            cloned_g, _, _ = clone_subgraph_into("id", src_oid, d_idm, d_uidm, dst_root, next_oid, dst_by_id, dst_by_uid)
            ti = dst_by_id[cloned_g]
            strip_transitions_from_ti(ti)
            set_trackitem_timing(ti, dst_by_id, c_st, c_en, preserve_inpoint=True, explicit_in_ticks=None)
            v8_new_item_ids.append(cloned_g)
            placed_v8_safety += 1
        print(f"[+] Placed {placed_v8_safety} visually verified Track V8 safety disclaimers (0 on harmless/animal clips)")
    else:
        safety_indices = [2, 5, 8, 12, 15, 19, 23, 27, 31, 35, 40, 45, 50, 55, 60, 65, 70]
        kb116_safety_oids = ["7586", "7587", "7588", "7591", "7597", "7605", "7606", "7611"]
        for i, clip_idx in enumerate(safety_indices):
            if clip_idx >= len(v3_body_clip_names):
                break
            cname = v3_body_clip_names[clip_idx]
            if cname in v3_clip_timeline_map:
                c_st, c_en, _ = v3_clip_timeline_map[cname]
                src_oid = kb116_safety_oids[i % len(kb116_safety_oids)]
                cloned_g, _, _ = clone_subgraph_into("id", src_oid, kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
                ti = dst_by_id[cloned_g]
                strip_transitions_from_ti(ti)
                set_trackitem_timing(ti, dst_by_id, c_st, c_en, preserve_inpoint=True, explicit_in_ticks=None)
                v8_new_item_ids.append(cloned_g)

    # 8. EXTEND UTILITY TRACKS (V2, V6, V7) WITH GLITCH GAPS, WARNING GAP, & DUAL-TRACK V2 TRANSITIONS
    print(f"[+] Extending Utility Tracks V2 (Brand Frame + Light Leaks), V6 (Logo), V7 (Watermark)...")

    def _subtract_intervals(spans, holes):
        res = list(spans)
        for h_st, h_en in sorted(holes):
            nxt = []
            for s_st, s_en in res:
                if h_en <= s_st or h_st >= s_en:
                    nxt.append((s_st, s_en))
                else:
                    if s_st < h_st:
                        nxt.append((s_st, h_st))
                    if h_en < s_en:
                        nxt.append((h_en, s_en))
            res = nxt
        return [sp for sp in res if sp[1] > sp[0]]

    def _split_spans_at_cuts(spans, cuts):
        res = list(spans)
        for ct in sorted(set(cuts)):
            nxt = []
            for s_st, s_en in res:
                if s_st < ct < s_en:
                    nxt.append((s_st, ct))
                    nxt.append((ct, s_en))
                else:
                    nxt.append((s_st, s_en))
            res = nxt
        return res

    for t_idx in [1, 5, 6]:  # V2, V6, V7
        cont = v_tracks[t_idx].find("./ClipTrack/ClipItems/TrackItems")
        t_ids = [r.attrib.get("ObjectRef") for r in cont if r.attrib.get("ObjectRef") in dst_by_id]
        if t_ids:
            base_ti = dst_by_id[t_ids[0]]
            strip_transitions_from_ti(base_ti)
            base_in_ticks = 995000950944000 if t_idx == 1 else (931359284856000 if t_idx == 5 else 893833268328000)
            sc_ref = base_ti.find(".//SubClip")
            if sc_ref is not None and sc_ref.attrib.get("ObjectRef") in dst_by_id:
                sc_el = dst_by_id[sc_ref.attrib["ObjectRef"]]
                c_ref = sc_el.find(".//Clip")
                if c_ref is not None and c_ref.attrib.get("ObjectRef") in dst_by_id:
                    ip_txt = dst_by_id[c_ref.attrib["ObjectRef"]].findtext(".//InPoint")
                    if ip_txt and int(ip_txt) > 0:
                        base_in_ticks = int(ip_txt)

            s_ids, s_uids = get_media_stops(t_ids[0], dst_by_id)
            if t_idx == 1:
                # V2 pauses during the 3 Glitch spacers and razors at f_c2_start, warn_start_f, warn_end_f, and all Light Leak cuts
                v2_spans = _subtract_intervals([(0, total_seq_ticks)], glitch_intervals)
                v2_razor_cuts = [
                    f_c2_start * TICKS_PER_FRAME,
                    warn_start_f * TICKS_PER_FRAME,
                    warn_end_f * TICKS_PER_FRAME,
                ] + list(lightleak_cut_ticks)
                v2_bounds = _split_spans_at_cuts(v2_spans, v2_razor_cuts)

                v2_seg_ids = []
                v2_end_map = {}
                v2_start_map = {}
                for seg_i, (v2_st, v2_en) in enumerate(v2_bounds):
                    if seg_i == 0:
                        seg_id = t_ids[0]
                    else:
                        seg_id, _, _ = clone_subgraph_into(
                            "id", t_ids[0], dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid, s_ids, s_uids
                        )
                    seg_el = dst_by_id[seg_id]
                    strip_transitions_from_ti(seg_el)
                    set_trackitem_timing(
                        seg_el, dst_by_id, v2_st, v2_en, preserve_inpoint=False, explicit_in_ticks=base_in_ticks + v2_st
                    )
                    v2_seg_ids.append(seg_id)
                    v2_end_map[v2_en] = seg_id
                    v2_start_map[v2_st] = seg_id

                # Attach AE.AE_Impact_Zoom_Blur transitions on V2 at f_c2_start and warn_start_f
                zb1_ct = f_c2_start * TICKS_PER_FRAME
                if zb1_ct in v2_end_map and zb1_ct in v2_start_map:
                    tr_v2_1, _, _ = clone_subgraph_into("id", "7362", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
                    set_transition_timing(
                        dst_by_id[tr_v2_1],
                        (f_c2_start - 7) * TICKS_PER_FRAME,
                        (f_c2_start + 7) * TICKS_PER_FRAME,
                        7 * TICKS_PER_FRAME,
                        has_outgoing=True,
                        has_incoming=True,
                    )
                    attach_transition_refs(dst_by_id[v2_end_map[zb1_ct]], dst_by_id[v2_start_map[zb1_ct]], tr_v2_1)
                    v2_trans_ids.append(tr_v2_1)

                zb2_ct = warn_start_f * TICKS_PER_FRAME
                if zb2_ct in v2_end_map and zb2_ct in v2_start_map:
                    tr_v2_2, _, _ = clone_subgraph_into("id", "7363", kb116_id, kb116_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
                    set_transition_timing(
                        dst_by_id[tr_v2_2],
                        (warn_start_f - 7) * TICKS_PER_FRAME,
                        (warn_start_f + 5) * TICKS_PER_FRAME,
                        7 * TICKS_PER_FRAME,
                        has_outgoing=True,
                        has_incoming=True,
                    )
                    attach_transition_refs(dst_by_id[v2_end_map[zb2_ct]], dst_by_id[v2_start_map[zb2_ct]], tr_v2_2)
                    v2_trans_ids.append(tr_v2_2)

                # Attach matching centered 12f AE.AE_Impact_Light_Leaks transitions on V2
                for ll_ct in sorted(lightleak_cut_ticks):
                    if ll_ct in v2_end_map and ll_ct in v2_start_map:
                        ll_v2_id, _, _ = clone_subgraph_into("id", "6706", kb122_id, kb122_uid, dst_root, next_oid, dst_by_id, dst_by_uid)
                        set_transition_timing(
                            dst_by_id[ll_v2_id],
                            ll_ct - 6 * TICKS_PER_FRAME,
                            ll_ct + 6 * TICKS_PER_FRAME,
                            6 * TICKS_PER_FRAME,
                            has_outgoing=True,
                            has_incoming=True,
                        )
                        attach_transition_refs(dst_by_id[v2_end_map[ll_ct]], dst_by_id[v2_start_map[ll_ct]], ll_v2_id)
                        v2_trans_ids.append(ll_v2_id)

                cont.clear()
                cont.attrib["Version"] = "1"
                for idx_v2, sid in enumerate(v2_seg_ids):
                    ET.SubElement(cont, "TrackItem", {"Index": str(idx_v2), "ObjectRef": str(sid)})
            else:
                # V6 (Only-Logo.png) and V7 (wtm.png) gap during Warning [warn_start_f..warn_end_f] AND during the 3 Glitch spacers
                util_holes = [(warn_start_f * TICKS_PER_FRAME, warn_end_f * TICKS_PER_FRAME)] + list(glitch_intervals)
                util_bounds = _subtract_intervals([(0, total_seq_ticks)], util_holes)
                util_seg_ids = []
                for seg_i, (u_st, u_en) in enumerate(util_bounds):
                    if seg_i == 0:
                        seg_id = t_ids[0]
                    else:
                        seg_id, _, _ = clone_subgraph_into(
                            "id", t_ids[0], dst_by_id, dst_by_uid, dst_root, next_oid, dst_by_id, dst_by_uid, s_ids, s_uids
                        )
                    seg_el = dst_by_id[seg_id]
                    strip_transitions_from_ti(seg_el)
                    set_trackitem_timing(
                        seg_el, dst_by_id, u_st, u_en, preserve_inpoint=False, explicit_in_ticks=base_in_ticks + u_st
                    )
                    util_seg_ids.append(seg_id)
                cont.clear()
                cont.attrib["Version"] = "1"
                for idx_u, sid in enumerate(util_seg_ids):
                    ET.SubElement(cont, "TrackItem", {"Index": str(idx_u), "ObjectRef": str(sid)})

    # 9. COMMIT NEW TRACK ITEMS & TRANSITION ITEMS INTO TRACK CONTAINERS
    def commit_items(track_el, item_ids):
        cont = track_el.find("./ClipTrack/ClipItems/TrackItems")
        if cont is None:
            clip_items = track_el.find("./ClipTrack/ClipItems")
            if clip_items is None:
                ct = track_el.find("ClipTrack")
                clip_items = ET.SubElement(ct, "ClipItems", {"Version": "1"})
            cont = ET.SubElement(clip_items, "TrackItems", {"Version": "1"})
        cont.clear()
        cont.attrib["Version"] = "1"
        for idx, oid in enumerate(item_ids):
            sub = ET.SubElement(cont, "TrackItem")
            sub.attrib["Index"] = str(idx)
            sub.attrib["ObjectRef"] = oid

    # Fill the 3 genuine 9-frame Glitch spacer gaps with Track V10 ('transition') and Track A8 ('TV Static Sound Effect - Bzz.mp4' In=31f..40f)
    if n_tv > 0 and len(glitch_intervals) == n_tv:
        for tv_i, (g_st, g_en) in enumerate(glitch_intervals):
            v10_el = dst_by_id[v10_ids[tv_i]]
            a8_el = dst_by_id[a8_ids[tv_i]]
            strip_transitions_from_ti(v10_el)
            strip_transitions_from_ti(a8_el)
            set_trackitem_timing(v10_el, dst_by_id, g_st, g_en, preserve_inpoint=False, explicit_in_ticks=0)
            set_trackitem_timing(
                a8_el, dst_by_id, g_st, g_en, preserve_inpoint=False, explicit_in_ticks=31 * TICKS_PER_FRAME
            )
        commit_items(v_tracks[9], v10_ids[:n_tv])
        commit_items(a_tracks[7], a8_ids[:n_tv])

    # Snap Track V9 / Track A7 89-frame Free YouTube CTA onto clean non-VO, non-V8, non-Glitch V3 clip starts
    if len(v_tracks) >= 9 and len(a_tracks) >= 7:
        v9_cont = v_tracks[8].find("./ClipTrack/ClipItems/TrackItems")
        a7_cont = a_tracks[6].find("./ClipTrack/ClipItems/TrackItems")
        v9_ids = [r.attrib.get("ObjectRef") for r in (v9_cont if v9_cont is not None else []) if r.attrib.get("ObjectRef") in dst_by_id]
        a7_ids = [r.attrib.get("ObjectRef") for r in (a7_cont if a7_cont is not None else []) if r.attrib.get("ObjectRef") in dst_by_id]
        n_cta = min(len(v9_ids), len(a7_ids))
        if n_cta > 0:
            cta_dur_ticks = 89 * TICKS_PER_FRAME
            if kb_id in EPISODE_CTA_CLIPS:
                cta_targets = list(EPISODE_CTA_CLIPS[kb_id])[:n_cta]
            else:
                v8_safety_set = set(EPISODE_V8_SAFETY_MAP.get(kb_id, {}).keys())
                cand_cta = [
                    c["clip_name"]
                    for c in (p1_manifest_clips + p2_normal_clips)
                    if c["duration_sec"] >= 5.0
                    and c["clip_name"] not in vo_clip_set_pre
                    and c["clip_name"] not in v8_safety_set
                    and c["clip_name"] not in set(glitch_before_targets)
                ]
                cta_targets = [
                    cand_cta[max(0, min(len(cand_cta) - 1, int(round((ci + 0.5) * len(cand_cta) / n_cta))))]
                    for ci in range(n_cta)
                ] if len(cand_cta) >= n_cta else []
            if len(cta_targets) == n_cta and all(cn in v3_clip_timeline_map for cn in cta_targets):
                for ci, cn in enumerate(cta_targets):
                    c_st, _, _ = v3_clip_timeline_map[cn]
                    strip_transitions_from_ti(dst_by_id[v9_ids[ci]])
                    strip_transitions_from_ti(dst_by_id[a7_ids[ci]])
                    set_trackitem_timing(dst_by_id[v9_ids[ci]], dst_by_id, c_st, c_st + cta_dur_ticks, preserve_inpoint=False, explicit_in_ticks=0)
                    set_trackitem_timing(dst_by_id[a7_ids[ci]], dst_by_id, c_st, c_st + cta_dur_ticks, preserve_inpoint=False, explicit_in_ticks=0)

    commit_items(v_tracks[2], v3_new_item_ids)  # V3
    commit_items(v_tracks[0], v1_new_item_ids)  # V1
    commit_items(v_tracks[3], v4_item_ids)      # V4 (clean GIF emojis)
    commit_items(a_tracks[0], a1_new_item_ids)  # A1
    commit_items(a_tracks[1], a2_new_item_ids)  # A2 (4 Intro VO Clauses + 15 Body VOs)
    commit_items(a_tracks[5], a6_new_item_ids)  # A6
    commit_items(a_tracks[4], a5_new_item_ids)  # A5
    commit_items(a_tracks[2], a3_new_item_ids)  # A3
    commit_items(a_tracks[3], [])               # A4 (0 stale SFX items)
    commit_items(v_tracks[7], v8_new_item_ids)  # V8

    commit_transitions(v_tracks[1], v2_trans_ids)  # V2 transitions (2 Zoom Blurs + 7 Light Leaks)
    commit_transitions(v_tracks[2], v3_trans_ids)  # V3 transitions (2 Zoom Blurs + 7 Light Leaks)
    commit_transitions(a_tracks[0], a1_trans_ids)  # A1 transitions (head fade + 12 crossfades + tail fade)
    commit_transitions(a_tracks[5], a6_trans_ids)  # A6 Custom Fade transition

    # 9.5 SANITIZE PROJECT HYGIENE (AGENTS.md Rule #7: 0 foreign donor/pek leakage, relink .aegraphic, clean bins)
    def sanitize_project_hygiene():
        import copy as _copy
        import re as _re
        import shutil as _shutil

        # 1. Clear all foreign .pek / ConformedAudioPath entries
        for el in dst_root.iter():
            if el.tag in ("PeakFilePath", "ConformedAudioPath"):
                el.text = ""
            elif el.tag == "project.settings.lastknowngoodprojectpath":
                el.text = "\\\\?\\" + prproj_path

        # 2. Relink any foreign .aegraphic files/bundles into <proj_dir>\Motion Graphics Template Media\...
        for m_el in dst_root.findall("Media"):
            fp_txt = (m_el.findtext("FilePath") or "").strip()
            if ".aegraphic" in fp_txt.lower() and os.path.normcase(proj_dir) not in os.path.normcase(fp_txt):
                sub_uuid = os.path.basename(os.path.dirname(fp_txt))
                fname = os.path.basename(fp_txt)
                src_ae_fp = fp_txt
                if not os.path.exists(src_ae_fp):
                    proj_parent = os.path.dirname(proj_dir)
                    for sib in sorted(os.listdir(proj_parent), reverse=True):
                        cand = os.path.join(proj_parent, sib, "Motion Graphics Template Media", sub_uuid, fname)
                        if os.path.exists(cand):
                            src_ae_fp = cand
                            break
                dst_ae_dir = os.path.join(proj_dir, "Motion Graphics Template Media", sub_uuid)
                os.makedirs(dst_ae_dir, exist_ok=True)
                dst_ae_fp = os.path.join(dst_ae_dir, fname)
                if os.path.exists(src_ae_fp) and not os.path.exists(dst_ae_fp):
                    if os.path.isdir(src_ae_fp):
                        _shutil.copytree(src_ae_fp, dst_ae_fp)
                    else:
                        _shutil.copy2(src_ae_fp, dst_ae_fp)
                for tnm in ("FilePath", "ActualMediaFilePath"):
                    tel = m_el.find(tnm)
                    if tel is not None:
                        tel.text = dst_ae_fp
                rel_ae = ".\\" + os.path.relpath(dst_ae_fp, proj_dir)
                for rpel in m_el.findall("RelativePath"):
                    rpel.text = rel_ae

        # 3. Find current episode's script folder, then sync <ClipName> on Media/MediaSource/Clip (and relink any transition-cloned foreign .mp4)
        actual_script_dir = None
        for dnm in os.listdir(proj_dir):
            if dnm.startswith("ITV-Moments-script-") and os.path.isdir(os.path.join(proj_dir, dnm)):
                actual_script_dir = dnm
                break
        media_fp_by_uid = {}
        for m_el in dst_root.findall("Media"):
            fp_txt = (m_el.findtext("FilePath") or "").strip()
            if fp_txt and "\\kb122\\itv-moments-script-82\\" in fp_txt.lower() and actual_script_dir:
                cand_local = os.path.join(proj_dir, actual_script_dir, os.path.basename(fp_txt))
                if os.path.exists(cand_local):
                    fp_txt = cand_local
                    for tnm in ("FilePath", "ActualMediaFilePath"):
                        tel = m_el.find(tnm)
                        if tel is not None:
                            tel.text = cand_local
                    rel_l = ".\\" + os.path.relpath(cand_local, proj_dir)
                    for rpel in m_el.findall("RelativePath"):
                        rpel.text = rel_l
            if fp_txt:
                bnm = os.path.basename(fp_txt)
                if "ObjectUID" in m_el.attrib:
                    media_fp_by_uid[m_el.attrib["ObjectUID"]] = (fp_txt, bnm)
                for cn_el in m_el.iter("ClipName"):
                    cn_el.text = bnm
        for src_tag in ("VideoMediaSource", "AudioMediaSource"):
            for ms_el in dst_root.findall(src_tag):
                m_ref = ms_el.find(".//Media")
                muid = m_ref.attrib.get("ObjectURef") if m_ref is not None else None
                if muid in media_fp_by_uid:
                    _, bnm = media_fp_by_uid[muid]
                    for cn_el in ms_el.iter("ClipName"):
                        cn_el.text = bnm
        for sc_el in dst_root.findall("SubClip"):
            sc_nm = (sc_el.findtext("Name") or "").strip()
            c_ref = sc_el.find(".//Clip")
            c_el = dst_by_id.get(c_ref.attrib.get("ObjectRef")) if c_ref is not None else None
            if sc_nm and c_el is not None:
                for cn_el in c_el.iter("ClipName"):
                    cn_el.text = sc_nm
        for mc_el in dst_root.findall("MasterClip"):
            mc_nm = (mc_el.findtext("Name") or "").strip()
            li_ref = mc_el.find("LoggingInfo")
            li_el = dst_by_id.get(li_ref.attrib.get("ObjectRef")) if li_ref is not None else None
            if mc_nm and li_el is not None:
                for cn_el in li_el.iter("ClipName"):
                    cn_el.text = mc_nm
        for li_el in dst_root.findall("ClipLoggingInfo"):
            for cn_el in li_el.iter("ClipName"):
                if cn_el.text and _re.search(r"kb\d+", cn_el.text, flags=_re.IGNORECASE):
                    cn_el.text = _re.sub(r"kb\d+", kb_id, cn_el.text, flags=_re.IGNORECASE)

        # 4. Sync episode script BinProjectItem name before Media/Bin sync
        source_bin_el = None
        script_bin_el = None
        recovered_bin_el = None
        for b_el in dst_root.findall("BinProjectItem"):
            bnm_el = b_el.find("./ProjectItem/Name")
            bnm = (bnm_el.text or "").strip() if bnm_el is not None else ""
            if bnm == "source":
                source_bin_el = b_el
            elif bnm.startswith("ITV-Moments-script-"):
                script_bin_el = b_el
                if actual_script_dir and bnm_el is not None:
                    bnm_el.text = actual_script_dir
            elif bnm == "Recovered Clips":
                recovered_bin_el = b_el

        # 5. Collect active MasterClip UIDs used ONLY by active TrackItems on the Sequence
        active_ti_ids = set()
        for trk in list(v_tracks) + list(a_tracks):
            for ti_ref in trk.findall(".//TrackItems/TrackItem"):
                if "ObjectRef" in ti_ref.attrib:
                    active_ti_ids.add(ti_ref.attrib["ObjectRef"])
        used_mc_uids = set()
        for ti_oid in active_ti_ids:
            ti_el = dst_by_id.get(ti_oid)
            if ti_el is None:
                continue
            sc_ref = ti_el.find(".//SubClip")
            sc_el = dst_by_id.get(sc_ref.attrib.get("ObjectRef")) if sc_ref is not None else None
            mc_ref = sc_el.find("MasterClip") if sc_el is not None else None
            if mc_ref is not None and "ObjectURef" in mc_ref.attrib:
                used_mc_uids.add(mc_ref.attrib["ObjectURef"])

        mc_info = {}
        for mc_el in dst_root.findall("MasterClip"):
            mc_uid = mc_el.attrib.get("ObjectUID")
            if not mc_uid:
                continue
            fp_found, bnm_found = "", (mc_el.findtext("Name") or "").strip()
            for cl_ref in mc_el.findall(".//Clip"):
                cl_el = dst_by_id.get(cl_ref.attrib.get("ObjectRef"))
                if cl_el is None:
                    continue
                sr_ref = cl_el.find(".//Source")
                sr_el = dst_by_id.get(sr_ref.attrib.get("ObjectRef")) if sr_ref is not None else None
                m_ref = sr_el.find(".//Media") if sr_el is not None else None
                muid = m_ref.attrib.get("ObjectURef") if m_ref is not None else None
                if muid in media_fp_by_uid:
                    fp_found, bnm_found = media_fp_by_uid[muid]
                    break
            if bnm_found and mc_el.find("Name") is not None and fp_found and os.path.normcase(proj_dir) in os.path.normcase(fp_found):
                mc_el.find("Name").text = bnm_found
            mc_info[mc_uid] = (fp_found, bnm_found)

        # 6. Prune ClipProjectItems pointing to foreign kb* episode media & deduplicate MasterClip bin items
        foreign_markers = tuple(
            f"\\kb{n}\\" for n in range(50, 200) if f"kb{n}" != kb_id.lower()
        ) + tuple(
            f"itv.kb{n}." for n in range(50, 200) if f"kb{n}" != kb_id.lower()
        )
        cpi_by_uid = {c.attrib["ObjectUID"]: c for c in dst_root.findall("ClipProjectItem") if "ObjectUID" in c.attrib}
        template_cpi = next(iter(cpi_by_uid.values()), None)

        bad_cpi_uids = set()
        represented_mc_uids = set()
        for c_uid, c_el in cpi_by_uid.items():
            mc_ref = c_el.find("MasterClip")
            mc_uid = mc_ref.attrib.get("ObjectURef") if mc_ref is not None else None
            fp_c, bnm_c = mc_info.get(mc_uid, ("", ""))
            nm_c = (c_el.findtext("./ProjectItem/Name") or "").strip()
            check_str = (fp_c + " " + bnm_c + " " + nm_c).lower()
            is_foreign = any(fm in check_str for fm in foreign_markers)
            if is_foreign and mc_uid not in used_mc_uids:
                bad_cpi_uids.add(c_uid)
            elif mc_uid:
                if fp_c and os.path.normcase(proj_dir) in os.path.normcase(fp_c):
                    nm_el = c_el.find("./ProjectItem/Name")
                    if nm_el is not None and bnm_c:
                        nm_el.text = bnm_c
                represented_mc_uids.add(mc_uid)

        for container_tag in ("BinProjectItem", "RootProjectItem"):
            for b_el in dst_root.findall(container_tag):
                items_el = b_el.find(".//ProjectItemContainer/Items")
                if items_el is None:
                    continue
                kept = [
                    it.attrib["ObjectURef"]
                    for it in items_el.findall("Item")
                    if it.attrib.get("ObjectURef") not in bad_cpi_uids
                    and not (
                        recovered_bin_el is not None
                        and it.attrib.get("ObjectURef") == recovered_bin_el.attrib.get("ObjectUID")
                    )
                ]
                items_el.clear()
                items_el.attrib["Version"] = "1"
                for idx_i, uref in enumerate(kept):
                    ET.SubElement(items_el, "Item", {"Index": str(idx_i), "ObjectURef": uref})

        # 7. Attach clean ClipProjectItem into source / ITV-Moments-script-XX for any orphan active MasterClip
        if template_cpi is not None:
            for mc_uid in sorted(used_mc_uids):
                if mc_uid in represented_mc_uids or mc_uid not in mc_info:
                    continue
                fp_m, bnm_m = mc_info[mc_uid]
                if not fp_m or os.path.normcase(proj_dir) not in os.path.normcase(fp_m):
                    continue
                target_bin = None
                if "\\source\\" in fp_m.lower() and source_bin_el is not None:
                    target_bin = source_bin_el
                elif "itv-moments-script-" in fp_m.lower() and script_bin_el is not None:
                    target_bin = script_bin_el
                if target_bin is None:
                    continue
                new_cpi = _copy.deepcopy(template_cpi)
                new_cpi_uid = str(uuid.uuid4())
                new_cpi.attrib["ObjectUID"] = new_cpi_uid
                nm_el = new_cpi.find("./ProjectItem/Name")
                if nm_el is not None:
                    nm_el.text = bnm_m
                mc_ref = new_cpi.find("MasterClip")
                if mc_ref is not None:
                    mc_ref.attrib["ObjectURef"] = mc_uid
                dst_root.append(new_cpi)
                items_el = target_bin.find(".//ProjectItemContainer/Items")
                if items_el is not None:
                    ET.SubElement(items_el, "Item", {"Index": str(len(items_el)), "ObjectURef": new_cpi_uid})
                represented_mc_uids.add(mc_uid)

    sanitize_project_hygiene()

    # 10. CANONICALIZE XML & WRITE OUTPUT
    print(f"[+] Canonicalizing XML AST and writing to {prproj_path}...")
    canonical_root, id_map = canonicalize_prproj(dst_root, bh_pool)

    with gzip.GzipFile(prproj_path, "wb", mtime=0.0) as f:
        f.write(b'<?xml version="1.0" encoding="UTF-8" ?>\n')
        f.write(ET.tostring(canonical_root, encoding="utf-8"))

    print(f"[✓] Project {kb_id.upper()} rebuild complete! Wrote canonical .prproj.")


if __name__ == "__main__":
    args = sys.argv[1:] if len(sys.argv) > 1 else ["all"]
    if args == ["all"]:
        for pid in ["kb118", "kb119", "kb120", "kb121", "kb122", "kb123", "kb124", "kb125", "kb126", "kb127", "kb128"]:
            rebuild_episode(pid)
    else:
        for pid in args:
            rebuild_episode(pid)
